window.OPUS_PAGES["025"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Pocket Metropolis</title>\n<meta name=\"description\" content=\"A tiny isometric city-builder toy in soft pastels. Place houses, towers, trees, parks, roads and water; watch little cars drive and the town light up at night.\">\n<meta name=\"theme-color\" content=\"#bfe3f2\">\n<style>\n  :root {\n    --grass: #a8d5a2;\n    --water: #7ec8e3;\n    --road: #d6d0c4;\n    --peach: #ffb5a7;\n    --blush: #fcd5ce;\n    --mint: #b8e0d2;\n    --lav: #cdb4db;\n    --ink: #4a4063;\n    --ink-2: #6f6689;\n    --ink-3: #9a93ad;\n    --cream: #fffaf3;\n    --cream-2: #fbf1e6;\n    --line: rgba(74, 64, 99, .12);\n    --shadow: 0 10px 28px -12px rgba(74, 64, 99, .45), 0 2px 0 rgba(255, 255, 255, .7) inset;\n    --round: ui-rounded, \"SF Pro Rounded\", \"Nunito\", \"Varela Round\", \"Quicksand\", \"Arial Rounded MT Bold\", \"M PLUS Rounded 1c\", \"URW Gothic\", \"Century Gothic\", \"Trebuchet MS\", sans-serif;\n  }\n  * { box-sizing: border-box; }\n  html, body {\n    margin: 0;\n    height: 100%;\n    overflow: hidden;\n    background: #bfe3f2;\n    color: var(--ink);\n    font-family: var(--round);\n    -webkit-font-smoothing: antialiased;\n    -webkit-tap-highlight-color: transparent;\n  }\n  #world {\n    position: fixed;\n    inset: 0;\n    touch-action: none;\n    outline: none;\n    cursor: pointer;\n  }\n  #world.panning { cursor: grabbing; }\n  #world canvas { width: 100%; height: 100%; display: block; }\n  #world:focus-visible { box-shadow: inset 0 0 0 3px rgba(74, 64, 99, .35); }\n\n  /* ---------- HUD ---------- */\n  .hud {\n    position: fixed;\n    z-index: 3;\n    pointer-events: none;\n  }\n  .hud > * { pointer-events: auto; }\n  .title-card {\n    top: 18px;\n    left: 18px;\n    background: var(--cream);\n    border-radius: 22px;\n    padding: 14px 18px 12px;\n    box-shadow: var(--shadow);\n    min-width: 238px;\n  }\n  .title-card h1 {\n    margin: 0;\n    font-size: 23px;\n    font-weight: 800;\n    letter-spacing: -.01em;\n    line-height: 1.05;\n    display: flex;\n    align-items: center;\n    gap: 9px;\n  }\n  .title-card h1 svg { width: 30px; height: 30px; flex: none; }\n  .title-card .tag {\n    margin: 4px 0 10px 39px;\n    font-size: 12.5px;\n    color: var(--ink-2);\n    letter-spacing: .01em;\n  }\n  .clock {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    padding-top: 10px;\n    border-top: 1.5px dashed var(--line);\n  }\n  .dial {\n    width: 30px;\n    height: 30px;\n    flex: none;\n  }\n  .clock-read {\n    font-variant-numeric: tabular-nums;\n    font-weight: 700;\n    font-size: 15px;\n    min-width: 5.6em;\n  }\n  .clock-read small { display: block; font-weight: 600; font-size: 11px; color: var(--ink-3); letter-spacing: .04em; }\n  .chip {\n    appearance: none;\n    border: 0;\n    font: inherit;\n    font-size: 12px;\n    font-weight: 700;\n    color: var(--ink);\n    background: var(--cream-2);\n    border-radius: 999px;\n    height: 30px;\n    min-width: 30px;\n    padding: 0 10px;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: 5px;\n    cursor: pointer;\n    transition: transform .2s cubic-bezier(.3, 1.6, .5, 1), background .2s ease;\n  }\n  .chip:hover { background: #f6e6d6; transform: translateY(-1px); }\n  .chip:active { transform: translateY(1px) scale(.96); }\n  .chip svg { width: 14px; height: 14px; }\n  .chip[aria-pressed=\"true\"] { background: var(--lav); }\n\n  .stats {\n    top: 18px;\n    right: 18px;\n    display: flex;\n    flex-direction: column;\n    align-items: flex-end;\n    gap: 10px;\n  }\n  .bubble {\n    position: relative;\n    background: var(--cream);\n    border-radius: 22px;\n    padding: 12px 16px 12px 14px;\n    box-shadow: var(--shadow);\n    display: flex;\n    align-items: center;\n    gap: 14px;\n    transform-origin: 15% 100%;\n  }\n  .bubble::after {\n    content: \"\";\n    position: absolute;\n    left: 30px;\n    bottom: -9px;\n    width: 18px;\n    height: 18px;\n    background: var(--cream);\n    border-radius: 0 0 6px 0;\n    transform: rotate(45deg);\n    box-shadow: 6px 6px 12px -8px rgba(74, 64, 99, .4);\n  }\n  .bubble.pop { animation: pop .5s cubic-bezier(.3, 1.8, .5, 1); }\n  @keyframes pop { 0% { transform: scale(1); } 35% { transform: scale(1.07, .95); } 100% { transform: scale(1); } }\n  .stat { display: grid; gap: 1px; }\n  .stat .k { font-size: 11px; font-weight: 700; color: var(--ink-3); letter-spacing: .08em; text-transform: uppercase; }\n  .stat .v { font-size: 22px; font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1.05; }\n  .stat .v small { font-size: 13px; font-weight: 700; color: var(--ink-2); }\n  .face { width: 40px; height: 40px; flex: none; }\n  .face .mouth { transition: d .4s ease; }\n  .meter {\n    width: 100%;\n    height: 6px;\n    border-radius: 3px;\n    background: #f1e7dc;\n    overflow: hidden;\n    margin-top: 4px;\n  }\n  .meter i {\n    display: block;\n    height: 100%;\n    width: 50%;\n    border-radius: 3px;\n    background: linear-gradient(90deg, #ffb5a7, #fcd5ce 40%, #b8e0d2);\n    transition: width .6s cubic-bezier(.3, 1.3, .5, 1);\n  }\n  .quick { display: flex; gap: 8px; }\n  .pill {\n    appearance: none;\n    border: 0;\n    font: inherit;\n    font-weight: 800;\n    font-size: 13.5px;\n    color: var(--ink);\n    background: var(--cream);\n    border-radius: 999px;\n    height: 40px;\n    padding: 0 16px 0 12px;\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    box-shadow: var(--shadow);\n    cursor: pointer;\n    transition: transform .25s cubic-bezier(.3, 1.6, .5, 1);\n  }\n  .pill svg { width: 20px; height: 20px; }\n  .pill:hover { transform: translateY(-2px) rotate(-1deg); }\n  .pill:active { transform: translateY(1px) scale(.97); }\n  .pill.icon { padding: 0; width: 40px; justify-content: center; }\n  .pill.icon .off { display: none; }\n  .pill.icon[aria-pressed=\"false\"] .on { display: none; }\n  .pill.icon[aria-pressed=\"false\"] .off { display: inline; }\n\n  /* ---------- toolbar ---------- */\n  .toolbar {\n    left: 50%;\n    bottom: 18px;\n    transform: translateX(-50%);\n    background: var(--cream);\n    border-radius: 26px;\n    padding: 8px;\n    box-shadow: var(--shadow);\n    display: flex;\n    gap: 6px;\n    max-width: calc(100vw - 24px);\n  }\n  .tool {\n    appearance: none;\n    border: 0;\n    font: inherit;\n    background: transparent;\n    color: var(--ink-2);\n    width: 72px;\n    padding: 6px 4px 7px;\n    border-radius: 18px;\n    display: grid;\n    justify-items: center;\n    gap: 3px;\n    cursor: pointer;\n    position: relative;\n    transition: background .25s ease, color .25s ease, transform .3s cubic-bezier(.3, 1.6, .5, 1);\n  }\n  .tool svg { width: 40px; height: 34px; transition: transform .35s cubic-bezier(.3, 1.8, .5, 1); }\n  .tool span { font-size: 12px; font-weight: 800; letter-spacing: .01em; }\n  .tool kbd {\n    position: absolute;\n    top: 4px;\n    right: 7px;\n    font: inherit;\n    font-size: 9.5px;\n    font-weight: 800;\n    color: var(--ink-3);\n    opacity: .8;\n  }\n  .tool:hover { background: var(--cream-2); color: var(--ink); }\n  .tool:hover svg { transform: translateY(-3px) scale(1.06); }\n  .tool[aria-pressed=\"true\"] {\n    background: var(--tint, var(--mint));\n    color: var(--ink);\n    transform: translateY(-6px);\n    box-shadow: 0 10px 18px -10px rgba(74, 64, 99, .55);\n  }\n  .tool[aria-pressed=\"true\"] svg { transform: translateY(-2px) scale(1.1); }\n  .tool[data-tool=\"bulldoze\"] { --tint: #ffd6cc; }\n  .tool[data-tool=\"house\"] { --tint: var(--peach); }\n  .tool[data-tool=\"tower\"] { --tint: var(--lav); }\n  .tool[data-tool=\"tree\"] { --tint: #cfe8c8; }\n  .tool[data-tool=\"park\"] { --tint: var(--mint); }\n  .tool[data-tool=\"road\"] { --tint: #ebe4d8; }\n  .tool[data-tool=\"water\"] { --tint: #c6e8f3; }\n  .sep { width: 1.5px; margin: 8px 2px; background: var(--line); border-radius: 1px; }\n\n  .toast {\n    left: 50%;\n    bottom: 118px;\n    transform: translate(-50%, 10px);\n    background: var(--ink);\n    color: var(--cream);\n    font-size: 13px;\n    font-weight: 700;\n    padding: 9px 16px;\n    border-radius: 999px;\n    opacity: 0;\n    transition: opacity .35s ease, transform .35s cubic-bezier(.3, 1.6, .5, 1);\n    white-space: nowrap;\n  }\n  .toast.show { opacity: 1; transform: translate(-50%, 0); }\n\n  .help {\n    left: 18px;\n    bottom: 22px;\n    font-size: 11.5px;\n    color: var(--ink-2);\n    background: rgba(255, 250, 243, .72);\n    padding: 8px 12px;\n    border-radius: 14px;\n    line-height: 1.6;\n    max-width: 260px;\n  }\n  .help b { color: var(--ink); }\n\n  .sr-only {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    margin: -1px;\n    overflow: hidden;\n    clip: rect(0 0 0 0);\n    white-space: nowrap;\n    border: 0;\n  }\n  :focus-visible { outline: 3px solid #8e7cc3; outline-offset: 2px; }\n  button:focus:not(:focus-visible) { outline: none; }\n\n  @media (max-width: 1100px) { .help { display: none; } }\n  @media (max-width: 760px) {\n    .title-card {\n      top: 10px; left: 10px; right: 10px;\n      padding: 8px 8px 8px 12px; min-width: 0; border-radius: 18px;\n      display: flex; align-items: center; justify-content: space-between; gap: 8px;\n    }\n    .title-card h1 { font-size: 16px; gap: 7px; white-space: nowrap; }\n    .title-card h1 svg { width: 22px; height: 22px; }\n    .title-card .tag { display: none; }\n    .clock { padding-top: 0; margin-top: 0; border-top: 0; gap: 5px; }\n    .dial { width: 22px; height: 22px; }\n    .clock-read { font-size: 13px; min-width: 3.3em; }\n    .clock-read small { font-size: 9.5px; }\n    .chip { height: 26px; min-width: 26px; padding: 0 7px; }\n    .chip .lbl { display: none; }\n    .stats {\n      top: 82px; left: 10px; right: 10px;\n      flex-direction: row; justify-content: space-between; align-items: center; gap: 8px;\n    }\n    .bubble { padding: 8px 12px 8px 9px; gap: 10px; border-radius: 18px; }\n    .bubble::after { display: none; }\n    .face { width: 28px; height: 28px; }\n    .stat .v { font-size: 16px; }\n    .stat .k { font-size: 9px; }\n    .meter { height: 4px; margin-top: 3px; }\n    .pill { height: 36px; font-size: 12px; padding: 0 12px 0 9px; }\n    .pill.icon { width: 36px; }\n    .pill svg { width: 17px; height: 17px; }\n    .toolbar { bottom: 10px; padding: 5px; gap: 2px; border-radius: 20px; }\n    .tool { width: 47px; padding: 5px 2px 5px; border-radius: 14px; }\n    .tool svg { width: 30px; height: 26px; }\n    .tool span { font-size: 9.5px; }\n    .tool kbd { display: none; }\n    .tool[aria-pressed=\"true\"] { transform: translateY(-4px); }\n    .sep { display: none; }\n    .toast { bottom: 92px; font-size: 12px; }\n  }\n  @media (max-width: 380px) {\n    .tool { width: 44px; }\n    .quick .pill .lbl { display: none; }\n    .quick .pill { width: 34px; padding: 0; justify-content: center; }\n  }\n  @media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after { transition-duration: .01ms !important; animation: none !important; }\n  }\n</style>\n</head>\n<body>\n<main id=\"world\" tabindex=\"0\" aria-label=\"Isometric town map. Click or tap a tile to build with the selected tool. Right-click or long-press to bulldoze. Drag to pan, scroll or pinch to zoom. Arrow keys move the cursor, Enter builds, Delete bulldozes.\" aria-describedby=\"status\">\n  <canvas id=\"scene\" aria-hidden=\"true\"></canvas>\n</main>\n\n<section class=\"hud title-card\" aria-label=\"Pocket Metropolis\">\n  <h1>\n    <svg viewBox=\"0 0 30 30\" aria-hidden=\"true\">\n      <path d=\"M15 4l11 5.5-11 5.5L4 9.5z\" fill=\"#a8d5a2\"/>\n      <path d=\"M4 9.5l11 5.5v11L4 20.5z\" fill=\"#8cbf86\"/>\n      <path d=\"M26 9.5L15 15v11l11-5.5z\" fill=\"#79ad74\"/>\n      <path d=\"M10.5 3.5l5 2.5v6.5l-5-2.5z\" fill=\"#ffb5a7\"/>\n      <path d=\"M15.5 6l3.5-1.8v6.5L15.5 12.5z\" fill=\"#f29a8a\"/>\n      <path d=\"M10.5 3.5l3.6-1.8 4.9 2.5-3.5 1.8z\" fill=\"#ffd3c9\"/>\n      <circle cx=\"21\" cy=\"12\" r=\"2.4\" fill=\"#b8e0d2\"/>\n    </svg>\n    Pocket Metropolis\n  </h1>\n  <p class=\"tag\">a tiny town that fits in your pocket</p>\n  <div class=\"clock\">\n    <svg class=\"dial\" viewBox=\"0 0 30 30\" aria-hidden=\"true\">\n      <circle cx=\"15\" cy=\"15\" r=\"13.5\" fill=\"#fbf1e6\" stroke=\"rgba(74,64,99,.15)\"/>\n      <path d=\"M1.5 15a13.5 13.5 0 0 1 27 0z\" fill=\"#dff1f8\"/>\n      <path d=\"M1.5 15a13.5 13.5 0 0 0 27 0z\" fill=\"#3d4a73\" opacity=\".85\"/>\n      <g id=\"dial-hand\"><circle cx=\"15\" cy=\"4.6\" r=\"3.1\" fill=\"#ffc86b\"/></g>\n      <circle cx=\"15\" cy=\"15\" r=\"1.6\" fill=\"#4a4063\"/>\n    </svg>\n    <p class=\"clock-read\" id=\"clock\" aria-live=\"off\">10:00<small>Day 1</small></p>\n    <button type=\"button\" class=\"chip\" id=\"pause\" aria-pressed=\"false\" aria-label=\"Pause the clock\">\n      <svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><rect x=\"3\" y=\"2.5\" width=\"2.8\" height=\"9\" rx=\"1\" fill=\"currentColor\"/><rect x=\"8.2\" y=\"2.5\" width=\"2.8\" height=\"9\" rx=\"1\" fill=\"currentColor\"/></svg>\n    </button>\n    <button type=\"button\" class=\"chip\" id=\"speed\" aria-label=\"Clock speed\">\n      <svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M1.5 3l5 4-5 4zM7 3l5 4-5 4z\" fill=\"currentColor\"/></svg><span class=\"lbl\" id=\"speed-lbl\">1×</span>\n    </button>\n  </div>\n</section>\n\n<section class=\"hud stats\" aria-label=\"Town statistics\">\n  <div class=\"bubble\" id=\"bubble\">\n    <svg class=\"face\" viewBox=\"0 0 40 40\" aria-hidden=\"true\">\n      <circle cx=\"20\" cy=\"20\" r=\"18\" fill=\"#ffe29a\"/>\n      <circle cx=\"20\" cy=\"20\" r=\"18\" fill=\"none\" stroke=\"#f0c46a\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"11\" cy=\"23\" rx=\"3.4\" ry=\"2.2\" fill=\"#ffb5a7\" opacity=\".8\"/>\n      <ellipse cx=\"29\" cy=\"23\" rx=\"3.4\" ry=\"2.2\" fill=\"#ffb5a7\" opacity=\".8\"/>\n      <circle cx=\"14\" cy=\"16.5\" r=\"2\" fill=\"#4a4063\"/>\n      <circle cx=\"26\" cy=\"16.5\" r=\"2\" fill=\"#4a4063\"/>\n      <path class=\"mouth\" id=\"mouth\" d=\"M13 24 Q20 30 27 24\" fill=\"none\" stroke=\"#4a4063\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n    </svg>\n    <div class=\"stat\">\n      <span class=\"k\">Population</span>\n      <span class=\"v\" id=\"pop\">0</span>\n    </div>\n    <div class=\"stat\">\n      <span class=\"k\">Happiness</span>\n      <span class=\"v\" id=\"happy\">—</span>\n      <span class=\"meter\" aria-hidden=\"true\"><i id=\"happy-bar\"></i></span>\n    </div>\n  </div>\n  <div class=\"quick\">\n    <button type=\"button\" class=\"pill\" id=\"random\">\n      <svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><rect x=\"2.5\" y=\"2.5\" width=\"15\" height=\"15\" rx=\"4\" fill=\"#cdb4db\"/><circle cx=\"7\" cy=\"7\" r=\"1.6\" fill=\"#fff\"/><circle cx=\"13\" cy=\"13\" r=\"1.6\" fill=\"#fff\"/><circle cx=\"13\" cy=\"7\" r=\"1.6\" fill=\"#fff\"/><circle cx=\"7\" cy=\"13\" r=\"1.6\" fill=\"#fff\"/><circle cx=\"10\" cy=\"10\" r=\"1.6\" fill=\"#fff\"/></svg>\n      <span class=\"lbl\">Random town</span>\n    </button>\n    <button type=\"button\" class=\"pill icon\" id=\"sound\" aria-pressed=\"true\" aria-label=\"Sound effects\">\n      <svg viewBox=\"0 0 20 20\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n        <path d=\"M3 8h3l4-3.5v11L6 12H3z\" fill=\"#fcd5ce\"/>\n        <path class=\"on\" d=\"M13 7.3c1.2 1.4 1.2 4 0 5.4M15.3 5.2c2.3 2.6 2.3 7 0 9.6\"/>\n        <path class=\"off\" d=\"M13.2 8l4 4m0-4l-4 4\"/>\n      </svg>\n    </button>\n  </div>\n</section>\n\n<nav class=\"hud toolbar\" aria-label=\"Building tools\">\n  <button type=\"button\" class=\"tool\" data-tool=\"house\" aria-pressed=\"true\" aria-label=\"House\">\n    <svg viewBox=\"0 0 40 34\" aria-hidden=\"true\"><path d=\"M20 22l14-7-14-7-14 7z\" fill=\"#a8d5a2\"/><path d=\"M11 17v-6l7 3.5v6z\" fill=\"#ffb5a7\"/><path d=\"M18 20.5v-6l9-4.5v6z\" fill=\"#f09a8b\"/><path d=\"M11 11l5-6 9 4.5-7 5z\" fill=\"#8e9aaf\"/><path d=\"M16 5l11 5.5-2 .1-9-4.5z\" fill=\"#a9b3c6\"/><rect x=\"21\" y=\"14.5\" width=\"2.4\" height=\"3\" rx=\".5\" fill=\"#fff6d6\" transform=\"skewY(-27)\" transform-origin=\"21 14.5\"/></svg>\n    <span>House</span><kbd>1</kbd>\n  </button>\n  <button type=\"button\" class=\"tool\" data-tool=\"tower\" aria-pressed=\"false\" aria-label=\"Tower\">\n    <svg viewBox=\"0 0 40 34\" aria-hidden=\"true\"><path d=\"M20 30l12-6-12-6-12 6z\" fill=\"#a8d5a2\"/><path d=\"M13 24V6l7 3.5v18z\" fill=\"#cdb4db\"/><path d=\"M20 27.5v-18l7-3.5v18z\" fill=\"#b39cc4\"/><path d=\"M13 6l7-3.5 7 3.5-7 3.5z\" fill=\"#e3d4ec\"/><g fill=\"#fff6d6\" opacity=\".95\"><rect x=\"22\" y=\"12\" width=\"1.6\" height=\"2.2\"/><rect x=\"24.6\" y=\"10.7\" width=\"1.6\" height=\"2.2\"/><rect x=\"22\" y=\"17\" width=\"1.6\" height=\"2.2\"/><rect x=\"24.6\" y=\"15.7\" width=\"1.6\" height=\"2.2\"/><rect x=\"22\" y=\"22\" width=\"1.6\" height=\"2.2\"/><rect x=\"24.6\" y=\"20.7\" width=\"1.6\" height=\"2.2\"/></g></svg>\n    <span>Tower</span><kbd>2</kbd>\n  </button>\n  <button type=\"button\" class=\"tool\" data-tool=\"tree\" aria-pressed=\"false\" aria-label=\"Tree\">\n    <svg viewBox=\"0 0 40 34\" aria-hidden=\"true\"><path d=\"M20 30l12-6-12-6-12 6z\" fill=\"#a8d5a2\"/><rect x=\"18.8\" y=\"17\" width=\"2.4\" height=\"8\" rx=\"1\" fill=\"#b08968\"/><circle cx=\"20\" cy=\"13\" r=\"7.5\" fill=\"#86c07f\"/><circle cx=\"17.5\" cy=\"10.5\" r=\"3.2\" fill=\"#a6d69f\"/></svg>\n    <span>Tree</span><kbd>3</kbd>\n  </button>\n  <button type=\"button\" class=\"tool\" data-tool=\"park\" aria-pressed=\"false\" aria-label=\"Park\">\n    <svg viewBox=\"0 0 40 34\" aria-hidden=\"true\"><path d=\"M20 28l15-7.5-15-7.5-15 7.5z\" fill=\"#bfe6b6\"/><path d=\"M9 19c6 1 10-2 14 0s6 3 8 1\" stroke=\"#f3e6cf\" stroke-width=\"2.6\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"26\" cy=\"17\" r=\"3\" fill=\"#7ec8e3\"/><circle cx=\"14\" cy=\"15\" r=\"3.4\" fill=\"#86c07f\"/><rect x=\"13.3\" y=\"17\" width=\"1.4\" height=\"3\" fill=\"#b08968\"/><circle cx=\"20\" cy=\"24\" r=\"1.1\" fill=\"#ffb5a7\"/><circle cx=\"23\" cy=\"22.5\" r=\"1.1\" fill=\"#cdb4db\"/></svg>\n    <span>Park</span><kbd>4</kbd>\n  </button>\n  <button type=\"button\" class=\"tool\" data-tool=\"road\" aria-pressed=\"false\" aria-label=\"Road\">\n    <svg viewBox=\"0 0 40 34\" aria-hidden=\"true\"><path d=\"M20 28l15-7.5-15-7.5-15 7.5z\" fill=\"#d6d0c4\"/><path d=\"M8.5 18.8l8.2 4.1M9 22.3l2.8-1.4\" stroke=\"#ece8df\" stroke-width=\"1.2\"/><path d=\"M12.5 17.5l15 7.5\" stroke=\"#fff\" stroke-width=\"1.4\" stroke-dasharray=\"2.6 2.4\" transform=\"translate(0 -2)\"/><rect x=\"28\" y=\"12\" width=\"1.2\" height=\"9\" fill=\"#8e8aa3\"/><circle cx=\"28.6\" cy=\"11.6\" r=\"1.8\" fill=\"#ffe29a\"/></svg>\n    <span>Road</span><kbd>5</kbd>\n  </button>\n  <button type=\"button\" class=\"tool\" data-tool=\"water\" aria-pressed=\"false\" aria-label=\"Water\">\n    <svg viewBox=\"0 0 40 34\" aria-hidden=\"true\"><path d=\"M20 28l15-7.5-15-7.5-15 7.5z\" fill=\"#7ec8e3\"/><path d=\"M12 20.5q2-1.3 4 0t4 0M20 23.5q2-1.3 4 0t4 0M18 17q2-1.3 4 0\" stroke=\"#e6f6fb\" stroke-width=\"1.3\" fill=\"none\" stroke-linecap=\"round\"/></svg>\n    <span>Water</span><kbd>6</kbd>\n  </button>\n  <span class=\"sep\" aria-hidden=\"true\"></span>\n  <button type=\"button\" class=\"tool\" data-tool=\"bulldoze\" aria-pressed=\"false\" aria-label=\"Bulldoze\">\n    <svg viewBox=\"0 0 40 34\" aria-hidden=\"true\"><rect x=\"8\" y=\"17\" width=\"18\" height=\"8\" rx=\"3\" fill=\"#ffc86b\"/><rect x=\"13\" y=\"10\" width=\"9\" height=\"8\" rx=\"2\" fill=\"#ffd98f\"/><rect x=\"15\" y=\"12\" width=\"5\" height=\"4\" rx=\"1\" fill=\"#dff1f8\"/><path d=\"M26 15h3l4 10h-7z\" fill=\"#9a93ad\"/><rect x=\"7\" y=\"24\" width=\"20\" height=\"5\" rx=\"2.5\" fill=\"#6f6689\"/><circle cx=\"10.5\" cy=\"26.5\" r=\"1.4\" fill=\"#cdc6da\"/><circle cx=\"17\" cy=\"26.5\" r=\"1.4\" fill=\"#cdc6da\"/><circle cx=\"23.5\" cy=\"26.5\" r=\"1.4\" fill=\"#cdc6da\"/></svg>\n    <span>Bulldoze</span><kbd>7</kbd>\n  </button>\n</nav>\n\n<p class=\"hud help\" aria-hidden=\"true\"><b>Click</b> to build &middot; <b>Right-click</b> to bulldoze<br><b>Drag</b> to pan &middot; <b>Scroll</b> to zoom<br>Parks near homes make people happy.</p>\n<p class=\"hud toast\" id=\"toast\" role=\"status\"></p>\n<p class=\"sr-only\" id=\"status\" aria-live=\"polite\"></p>\n\n<script>\n(() => {\n  'use strict';\n\n  /* ================================================================\n     Pocket Metropolis — a 12×12 isometric toy town\n     ================================================================ */\n  const N = 12;\n  const EMPTY = 0, WATER = 1, ROAD = 2, HOUSE = 3, TOWER = 4, TREE = 5, PARK = 6;\n  const TOOL_TYPE = { house: HOUSE, tower: TOWER, tree: TREE, park: PARK, road: ROAD, water: WATER, bulldoze: EMPTY };\n  const TYPE_NAME = ['grass', 'water', 'road', 'house', 'tower', 'tree', 'park'];\n  const TWH = 32, THH = 16;          // half tile width / height in world pixels\n  const STORE_KEY = 'pocket-metropolis-v1';\n\n  const world = document.getElementById('world');\n  const canvas = document.getElementById('scene');\n  const ctx = canvas.getContext('2d');\n  const statusEl = document.getElementById('status');\n  const toastEl = document.getElementById('toast');\n  const popEl = document.getElementById('pop');\n  const happyEl = document.getElementById('happy');\n  const happyBar = document.getElementById('happy-bar');\n  const mouthEl = document.getElementById('mouth');\n  const bubbleEl = document.getElementById('bubble');\n  const clockEl = document.getElementById('clock');\n  const dialHand = document.getElementById('dial-hand');\n  const pauseBtn = document.getElementById('pause');\n  const speedBtn = document.getElementById('speed');\n  const speedLbl = document.getElementById('speed-lbl');\n  const soundBtn = document.getElementById('sound');\n  const toolBtns = Array.from(document.querySelectorAll('.tool'));\n\n  const reduceMQ = window.matchMedia('(prefers-reduced-motion: reduce)');\n  let reduced = reduceMQ.matches;\n\n  /* ---------------- guarded storage ---------------- */\n  const store = {\n    get(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } },\n    set(k, v) { try { window.localStorage.setItem(k, v); } catch (e) { /* file:// may refuse */ } }\n  };\n\n  /* ---------------- helpers ---------------- */\n  let seed = (Date.now() & 0xffffffff) >>> 0;\n  function rand() {\n    seed = (seed + 0x6D2B79F5) >>> 0;\n    let t = seed;\n    t = Math.imul(t ^ (t >>> 15), t | 1);\n    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  }\n  function hash(a, b, c) {\n    let h = Math.imul(a + 1, 374761393) ^ Math.imul(b + 7, 668265263) ^ Math.imul(c + 13, 2246822519);\n    h = Math.imul(h ^ (h >>> 13), 1274126177);\n    return ((h ^ (h >>> 16)) >>> 0) / 4294967296;\n  }\n  const clamp = (x, a, b) => (x < a ? a : x > b ? b : x);\n  const lerp = (a, b, t) => a + (b - a) * t;\n  function hexRGB(h) { return [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)]; }\n\n  /* ---------------- palette ---------------- */\n  const C = {\n    grass: hexRGB('#a8d5a2'), grassDeep: hexRGB('#94c78e'), lawn: hexRGB('#bde4b4'),\n    water: hexRGB('#7ec8e3'), waterDeep: hexRGB('#62b3d3'), foam: hexRGB('#e9f7fb'), sand: hexRGB('#f1e4c8'),\n    road: hexRGB('#d6d0c4'), walk: hexRGB('#ebe6dc'), curb: hexRGB('#c3bcae'), paint: hexRGB('#fffdf6'),\n    path: hexRGB('#f3e6cf'), trunk: hexRGB('#b08968'),\n    leaf: [hexRGB('#86c07f'), hexRGB('#79b774'), hexRGB('#95cb87')], leafHi: hexRGB('#b2dea9'),\n    soilTop: hexRGB('#e2c3a3'), soil: hexRGB('#d2ad8a'), soilDeep: hexRGB('#bf9676'),\n    walls: [hexRGB('#ffb5a7'), hexRGB('#fcd5ce'), hexRGB('#b8e0d2'), hexRGB('#cdb4db')],\n    roofs: [hexRGB('#8e9aaf'), hexRGB('#f4978e'), hexRGB('#84a9ac'), hexRGB('#b5838d'), hexRGB('#9d8fbd')],\n    trim: hexRGB('#fff8ee'), door: hexRGB('#8d7b9e'), glass: hexRGB('#dff1f8'), glow: hexRGB('#ffe7a1'),\n    lamp: hexRGB('#8e8aa3'), metal: hexRGB('#b9b3c9'),\n    cars: [hexRGB('#ff8fab'), hexRGB('#ffc86b'), hexRGB('#7fb8e6'), hexRGB('#fffaf3'), hexRGB('#b39cd0'), hexRGB('#8fd3b6')],\n    shirts: [hexRGB('#ff8fab'), hexRGB('#7fb8e6'), hexRGB('#ffc86b'), hexRGB('#b39cd0'), hexRGB('#f4978e'), hexRGB('#6fc2a4')],\n    flowers: [hexRGB('#ff9fb2'), hexRGB('#fff1a8'), hexRGB('#c9b6f2'), hexRGB('#ffffff')]\n  };\n\n  /* ================================================================\n     Town state\n     ================================================================ */\n  const grid = new Uint8Array(N * N);\n  const vari = new Uint8Array(N * N);\n  const born = new Float64Array(N * N);\n  const IDX = (i, j) => i + j * N;\n  const inside = (i, j) => i >= 0 && j >= 0 && i < N && j < N;\n  const at = (i, j) => (inside(i, j) ? grid[IDX(i, j)] : -1);\n\n  function roadMask(i, j) {\n    let m = 0;\n    if (at(i + 1, j) === ROAD) m |= 1;\n    if (at(i, j + 1) === ROAD) m |= 2;\n    if (at(i - 1, j) === ROAD) m |= 4;\n    if (at(i, j - 1) === ROAD) m |= 8;\n    return m;\n  }\n\n  function save() {\n    let s = '';\n    for (let k = 0; k < N * N; k++) s += grid[k].toString() + String.fromCharCode(97 + (vari[k] % 26));\n    store.set(STORE_KEY, JSON.stringify({ v: 1, day: dayCount, t: timeOfDay, g: s }));\n  }\n  let saveTimer = 0;\n  function saveSoon() { clearTimeout(saveTimer); saveTimer = setTimeout(save, 350); }\n  function load() {\n    const raw = store.get(STORE_KEY);\n    if (!raw) return false;\n    try {\n      const d = JSON.parse(raw);\n      if (!d || typeof d.g !== 'string' || d.g.length !== N * N * 2) return false;\n      for (let k = 0; k < N * N; k++) {\n        const t = +d.g[k * 2];\n        grid[k] = t >= 0 && t <= 6 ? t : 0;\n        vari[k] = (d.g.charCodeAt(k * 2 + 1) - 97 + 26) % 26;\n      }\n      if (typeof d.t === 'number') timeOfDay = clamp(d.t, 0, 0.999);\n      if (typeof d.day === 'number') dayCount = Math.max(1, Math.floor(d.day));\n      return true;\n    } catch (e) { return false; }\n  }\n\n  /* ---------------- a charming random town ---------------- */\n  function randomTown(animate) {\n    grid.fill(EMPTY);\n    for (let k = 0; k < N * N; k++) vari[k] = Math.floor(rand() * 26);\n    // a lazy river along one side, sometimes widening into a pond\n    const riverSide = rand() < 0.5;\n    let r = 8 + Math.floor(rand() * 3);\n    for (let s = 0; s < N; s++) {\n      if (s > 0 && rand() < 0.45) r = clamp(r + (rand() < 0.5 ? -1 : 1), 8, 10);\n      const [i, j] = riverSide ? [s, r] : [r, s];\n      grid[IDX(i, j)] = WATER;\n      if (rand() < 0.3 && inside(riverSide ? i : i + 1, riverSide ? j + 1 : j)) grid[IDX(riverSide ? i : i + 1, riverSide ? j + 1 : j)] = WATER;\n    }\n    // two avenues and a cross street\n    const a1 = 2 + Math.floor(rand() * 2), a2 = 6 + Math.floor(rand() * 2), cs = 3 + Math.floor(rand() * 3);\n    const lim = riverSide ? 7 : N;\n    const along = (i, j) => { if (inside(i, j) && grid[IDX(i, j)] !== WATER) grid[IDX(i, j)] = ROAD; };\n    for (let s = 0; s < N; s++) {\n      if (riverSide) { if (s < lim) { along(a1, s); along(a2, s); } along(s, cs); }\n      else { if (s < 8) { along(s, a1); along(s, a2); } along(cs, s); }\n    }\n    // a little bridge over the river\n    const bridgeAt = riverSide ? a2 : a2;\n    for (let s = 0; s < N; s++) {\n      const i = riverSide ? bridgeAt : s, j = riverSide ? s : bridgeAt;\n      if (s >= 7 && inside(i, j)) grid[IDX(i, j)] = ROAD;\n    }\n    // homes beside the roads, towers in the middle\n    const cx = (N - 1) / 2 - 1, cy = (N - 1) / 2 - 1;\n    for (let j = 0; j < N; j++) {\n      for (let i = 0; i < N; i++) {\n        const k = IDX(i, j);\n        if (grid[k] !== EMPTY) continue;\n        const nearRoad = roadMask(i, j) !== 0;\n        const d = Math.hypot(i - cx, j - cy);\n        if (nearRoad) {\n          if (d < 3.2 && rand() < 0.62) grid[k] = TOWER;\n          else if (rand() < 0.72) grid[k] = HOUSE;\n        }\n      }\n    }\n    // parks sprinkled next to homes, trees along the banks and in gaps\n    let parks = 0;\n    for (let tries = 0; tries < 60 && parks < 4; tries++) {\n      const i = Math.floor(rand() * N), j = Math.floor(rand() * N), k = IDX(i, j);\n      if (grid[k] === EMPTY || (grid[k] === HOUSE && rand() < 0.3)) {\n        grid[k] = PARK; parks++;\n        if (rand() < 0.5 && at(i + 1, j) === EMPTY) { grid[IDX(i + 1, j)] = PARK; parks++; }\n      }\n    }\n    for (let j = 0; j < N; j++) {\n      for (let i = 0; i < N; i++) {\n        const k = IDX(i, j);\n        if (grid[k] !== EMPTY) continue;\n        const bank = at(i + 1, j) === WATER || at(i - 1, j) === WATER || at(i, j + 1) === WATER || at(i, j - 1) === WATER;\n        if (rand() < (bank ? 0.6 : 0.34)) grid[k] = TREE;\n      }\n    }\n    const now = performance.now();\n    for (let k = 0; k < N * N; k++) {\n      // cascade the pop-in from the centre outwards\n      const i = k % N, j = (k / N) | 0;\n      born[k] = animate && !reduced ? now + (Math.abs(i - N / 2) + Math.abs(j - N / 2)) * 55 + rand() * 60 : 0;\n    }\n    rebuildLife();\n    recount(true);\n    saveSoon();\n  }\n\n  /* ================================================================\n     Time of day and light\n     ================================================================ */\n  let timeOfDay = 0.42;    // 0 = midnight\n  let dayCount = 1;\n  let clockSpeed = 1;      // 1×, 4×, 12×\n  let paused = false;\n  const DAY_SECONDS = 240; // one full day at 1×\n\n  // keyframes: t, ambient light rgb, sky top, sky horizon\n  const KEYS = [\n    [0.00, [0.42, 0.45, 0.72], '#1f2a4f', '#3d4f7c'],\n    [0.21, [0.44, 0.46, 0.72], '#26325c', '#4d5e8e'],\n    [0.26, [1.00, 0.80, 0.82], '#9cb8e8', '#ffc9d3'],\n    [0.33, [1.00, 0.97, 0.95], '#9fd3ee', '#fbe9e2'],\n    [0.50, [1.00, 1.00, 1.00], '#8fcdeb', '#e4f5fb'],\n    [0.68, [1.00, 0.97, 0.94], '#9bcbe8', '#fdebdc'],\n    [0.75, [1.00, 0.76, 0.68], '#8a7bb0', '#ffb8a1'],\n    [0.80, [0.52, 0.50, 0.76], '#3a3d6e', '#8a6f9a'],\n    [1.00, [0.42, 0.45, 0.72], '#1f2a4f', '#3d4f7c']\n  ];\n  const light = { amb: [1, 1, 1], skyTop: [143, 205, 235], skyLow: [228, 245, 251], night: 0, sunX: 0, sunY: 1, sunUp: 1 };\n  function mixHex(a, b, t) { const A = hexRGB(a), B = hexRGB(b); return [lerp(A[0], B[0], t), lerp(A[1], B[1], t), lerp(A[2], B[2], t)]; }\n  function updateLight() {\n    const t = timeOfDay;\n    let k = 0;\n    while (k < KEYS.length - 2 && KEYS[k + 1][0] <= t) k++;\n    const a = KEYS[k], b = KEYS[k + 1];\n    const f = clamp((t - a[0]) / (b[0] - a[0]), 0, 1);\n    const s = f * f * (3 - 2 * f);\n    light.amb = [lerp(a[1][0], b[1][0], s), lerp(a[1][1], b[1][1], s), lerp(a[1][2], b[1][2], s)];\n    light.skyTop = mixHex(a[2], b[2], s);\n    light.skyLow = mixHex(a[3], b[3], s);\n    // how much the lamps and windows should glow\n    const sunH = Math.sin((t - 0.25) * Math.PI * 2);\n    light.night = clamp(0.25 - sunH * 2.2, 0, 1);\n    light.sunUp = sunH;\n    // sun direction across the sky, used for face shading and shadow direction\n    light.sunX = Math.cos((t - 0.25) * Math.PI * 2);\n  }\n\n  /* lit colour: base rgb * ambient * face factor -> css */\n  function lit(rgb, f, a) {\n    const r = clamp(rgb[0] * light.amb[0] * f, 0, 255) | 0;\n    const g = clamp(rgb[1] * light.amb[1] * f, 0, 255) | 0;\n    const b = clamp(rgb[2] * light.amb[2] * f, 0, 255) | 0;\n    return a === undefined ? 'rgb(' + r + ',' + g + ',' + b + ')' : 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';\n  }\n  function emit(rgb, a) { return 'rgba(' + rgb[0] + ',' + rgb[1] + ',' + rgb[2] + ',' + a + ')'; }\n\n  /* ================================================================\n     Camera\n     ================================================================ */\n  let W = 0, H = 0, DPR = 1;\n  const cam = { x: 0, y: 0, zoom: 1, fit: 1, user: 1 };\n  function fitCamera(keepUser) {\n    const boardW = N * TWH * 2, boardH = N * THH * 2 + 150;\n    const topPad = W < 760 ? 140 : 110, botPad = W < 760 ? 88 : 120;\n    const availW = W < 760 ? W + 24 : W - 80, availH = H - topPad - botPad;\n    cam.fit = clamp(Math.min(availW / boardW, availH / boardH), 0.3, 2.4);\n    if (!keepUser) cam.user = 1;\n    cam.zoom = cam.fit * cam.user;\n    // board centre in world space is (0, N*THH); leave room for towers above\n    cam.x = W / 2;\n    cam.y = topPad + availH / 2 - (N * THH - 40) * cam.zoom;\n  }\n  function toWorld(sx, sy) { return [(sx - cam.x) / cam.zoom, (sy - cam.y) / cam.zoom]; }\n  function tileAt(sx, sy) {\n    const [wx, wy] = toWorld(sx, sy);\n    const a = wx / TWH, b = wy / THH;\n    const i = Math.floor((b + a) / 2), j = Math.floor((b - a) / 2);\n    return inside(i, j) ? [i, j] : null;\n  }\n  function zoomAt(sx, sy, factor) {\n    const nz = clamp(cam.zoom * factor, cam.fit * 0.55, cam.fit * 3.2);\n    const f = nz / cam.zoom;\n    cam.x = sx - (sx - cam.x) * f;\n    cam.y = sy - (sy - cam.y) * f;\n    cam.zoom = nz;\n    cam.user = nz / cam.fit;\n  }\n  function resize() {\n    const prevW = W;\n    W = window.innerWidth; H = window.innerHeight;\n    if (prevW && Math.abs(W - prevW) / prevW > 0.3) cam.user = 1; // a new kind of screen: start from a fresh fit\n    DPR = Math.min(2, window.devicePixelRatio || 1);\n    canvas.width = Math.round(W * DPR);\n    canvas.height = Math.round(H * DPR);\n    fitCamera(true);\n    makeStars();\n  }\n\n  /* ================================================================\n     Drawing primitives (world px: x right, y down; P(x,y,z) iso)\n     ================================================================ */\n  const PX = (x, y) => (x - y) * TWH;\n  const PY = (x, y, z) => (x + y) * THH - z;\n  function pathQuad(x0, y0, z0, x1, y1, z1, x2, y2, z2, x3, y3, z3) {\n    ctx.beginPath();\n    ctx.moveTo(PX(x0, y0), PY(x0, y0, z0));\n    ctx.lineTo(PX(x1, y1), PY(x1, y1, z1));\n    ctx.lineTo(PX(x2, y2), PY(x2, y2, z2));\n    ctx.lineTo(PX(x3, y3), PY(x3, y3, z3));\n    ctx.closePath();\n  }\n  function diamond(x0, y0, x1, y1, z) { pathQuad(x0, y0, z, x1, y0, z, x1, y1, z, x0, y1, z); }\n\n  /* a box with ambient occlusion toward the ground; returns nothing */\n  function box(x0, y0, x1, y1, z0, z1, rgb, opt) {\n    const sunL = light.sunX; // -1 morning (light from the left) .. 1 evening\n    const soft = opt && opt.soft || 0;\n    const fl = 0.9 + soft * 0.05 - 0.07 * sunL, fr = 0.76 + soft * 0.12 + 0.07 * sunL;\n    const topF = opt && opt.topF || 1.04;\n    // left face (y = y1)\n    pathQuad(x0, y1, z0, x1, y1, z0, x1, y1, z1, x0, y1, z1);\n    let g = ctx.createLinearGradient(0, PY(x0, y1, z1), 0, PY(x0, y1, z0) + 6);\n    g.addColorStop(0, lit(rgb, fl));\n    g.addColorStop(1, lit(rgb, fl * 0.8));\n    ctx.fillStyle = g;\n    ctx.fill();\n    // right face (x = x1)\n    pathQuad(x1, y1, z0, x1, y0, z0, x1, y0, z1, x1, y1, z1);\n    g = ctx.createLinearGradient(0, PY(x1, y0, z1), 0, PY(x1, y1, z0) + 6);\n    g.addColorStop(0, lit(rgb, fr));\n    g.addColorStop(1, lit(rgb, fr * 0.8));\n    ctx.fillStyle = g;\n    ctx.fill();\n    // top\n    if (!(opt && opt.noTop)) {\n      pathQuad(x0, y0, z1, x1, y0, z1, x1, y1, z1, x0, y1, z1);\n      ctx.fillStyle = lit(opt && opt.top || rgb, topF);\n      ctx.fill();\n    }\n    // a soft highlight along the front vertical edge\n    ctx.beginPath();\n    ctx.moveTo(PX(x1, y1), PY(x1, y1, z0));\n    ctx.lineTo(PX(x1, y1), PY(x1, y1, z1));\n    ctx.strokeStyle = 'rgba(255,255,255,' + (0.35 * (1 - light.night * 0.7)).toFixed(3) + ')';\n    ctx.lineWidth = 0.8;\n    ctx.stroke();\n  }\n\n  /* windows on a face; lit at night (emissive) */\n  function windowsLeft(x0, x1, y, z0, z1, cols, rows, key, w, h) {\n    for (let r = 0; r < rows; r++) {\n      for (let c = 0; c < cols; c++) {\n        const fx = x0 + (x1 - x0) * (c + 0.5) / cols, fz = z0 + (z1 - z0) * (r + 0.5) / rows;\n        const on = hash(key, r, c) < 0.72;\n        winQuad(fx - w / 2, y, fx + w / 2, y, fz - h / 2, fz + h / 2, on);\n      }\n    }\n  }\n  function windowsRight(y0, y1, x, z0, z1, cols, rows, key, w, h) {\n    for (let r = 0; r < rows; r++) {\n      for (let c = 0; c < cols; c++) {\n        const fy = y1 - (y1 - y0) * (c + 0.5) / cols, fz = z0 + (z1 - z0) * (r + 0.5) / rows;\n        const on = hash(key + 99, r, c) < 0.66;\n        winQuad(x, fy + w / 2, x, fy - w / 2, fz - h / 2, fz + h / 2, on);\n      }\n    }\n  }\n  function winQuad(xa, ya, xb, yb, za, zb, on) {\n    pathQuad(xa, ya, za, xb, yb, za, xb, yb, zb, xa, ya, zb);\n    const n = light.night;\n    if (on && n > 0.05) {\n      const day = lit(C.glass, 0.95);\n      ctx.fillStyle = day;\n      ctx.fill();\n      ctx.fillStyle = emit(C.glow, n.toFixed(3));\n      ctx.fill();\n      glows.push(PX((xa + xb) / 2, (ya + yb) / 2), PY((xa + xb) / 2, (ya + yb) / 2, (za + zb) / 2), 5, 0.22 * n);\n    } else {\n      ctx.fillStyle = lit(C.glass, 0.95 - 0.3 * n);\n      ctx.fill();\n    }\n  }\n\n  /* ================================================================\n     Life: cars on roads, strollers in parks, dust puffs\n     ================================================================ */\n  const cars = [];\n  const walkers = [];\n  const puffs = [];\n  for (let q = 0; q < 90; q++) puffs.push({ on: false });\n  const rings = [];\n  for (let q = 0; q < 12; q++) rings.push({ on: false });\n\n  function roadTiles() {\n    const out = [];\n    for (let k = 0; k < N * N; k++) if (grid[k] === ROAD) out.push(k);\n    return out;\n  }\n  function spawnCar(k) {\n    const i = k % N, j = (k / N) | 0;\n    const car = { i, j, pi: i, pj: j, ni: i, nj: j, t: 1, speed: 0.75 + rand() * 0.5, col: C.cars[Math.floor(rand() * C.cars.length)], x: i + 0.5, y: j + 0.5, dx: 1, dy: 0 };\n    pickNext(car);\n    cars.push(car);\n  }\n  function pickNext(car) {\n    const opts = [];\n    const dirs = [[1, 0], [0, 1], [-1, 0], [0, -1]];\n    for (const d of dirs) {\n      const ni = car.i + d[0], nj = car.j + d[1];\n      if (at(ni, nj) === ROAD && !(ni === car.pi && nj === car.pj)) opts.push([ni, nj]);\n    }\n    if (!opts.length && at(car.pi, car.pj) === ROAD && !(car.pi === car.i && car.pj === car.j)) opts.push([car.pi, car.pj]);\n    if (!opts.length) { car.ni = car.i; car.nj = car.j; car.t = 1; return; }\n    const pick = opts[Math.floor(rand() * opts.length)];\n    car.ni = pick[0]; car.nj = pick[1]; car.t = 0;\n  }\n  function syncCars() {\n    const roads = roadTiles();\n    // drop cars whose road vanished\n    for (let q = cars.length - 1; q >= 0; q--) {\n      const c = cars[q];\n      if (at(c.i, c.j) !== ROAD || (c.t < 1 && at(c.ni, c.nj) !== ROAD)) cars.splice(q, 1);\n    }\n    const target = Math.min(16, Math.floor(roads.length / 3));\n    while (cars.length > target) cars.pop();\n    let guard = 0;\n    while (cars.length < target && roads.length && guard++ < 40) spawnCar(roads[Math.floor(rand() * roads.length)]);\n  }\n  function updateCars(dt) {\n    for (const c of cars) {\n      if (c.ni === c.i && c.nj === c.j) { pickNext(c); if (c.ni === c.i && c.nj === c.j) { c.x = c.i + 0.5; c.y = c.j + 0.5; continue; } }\n      c.t += dt * c.speed * (reduced ? 0.5 : 1);\n      if (c.t >= 1) {\n        c.pi = c.i; c.pj = c.j;\n        c.i = c.ni; c.j = c.nj;\n        c.t = 0;\n        pickNext(c);\n      }\n      const dx = c.ni - c.i, dy = c.nj - c.j;\n      if (dx || dy) { c.dx = dx; c.dy = dy; }\n      // drive on the right-hand side of the road\n      const ox = -c.dy * 0.17, oy = c.dx * 0.17;\n      c.x = c.i + 0.5 + dx * c.t + ox;\n      c.y = c.j + 0.5 + dy * c.t + oy;\n    }\n  }\n\n  function rebuildLife() {\n    walkers.length = 0;\n    for (let k = 0; k < N * N; k++) {\n      if (grid[k] !== PARK) continue;\n      const n = 2 + (vari[k] % 2);\n      for (let q = 0; q < n; q++) {\n        walkers.push({ k, x: 0.25 + rand() * 0.5, y: 0.25 + rand() * 0.5, tx: 0.5, ty: 0.5, wait: rand() * 2, col: C.shirts[Math.floor(rand() * C.shirts.length)], ph: rand() * 6 });\n      }\n    }\n    syncCars();\n  }\n  function updateWalkers(dt) {\n    for (const w of walkers) {\n      if (grid[w.k] !== PARK) continue;\n      if (w.wait > 0) { w.wait -= dt; continue; }\n      const dx = w.tx - w.x, dy = w.ty - w.y, d = Math.hypot(dx, dy);\n      if (d < 0.02) { w.tx = 0.18 + rand() * 0.64; w.ty = 0.18 + rand() * 0.64; w.wait = 0.6 + rand() * 2.4; continue; }\n      const sp = 0.16 * dt * (reduced ? 0.5 : 1);\n      w.x += dx / d * Math.min(sp, d);\n      w.y += dy / d * Math.min(sp, d);\n      w.ph += dt * 9;\n    }\n  }\n\n  function puff(i, j, n) {\n    for (let q = 0; q < n; q++) {\n      const p = puffs.find(o => !o.on);\n      if (!p) break;\n      const a = rand() * Math.PI * 2, r = 0.1 + rand() * 0.35;\n      p.on = true;\n      p.x = i + 0.5 + Math.cos(a) * r * 0.5; p.y = j + 0.5 + Math.sin(a) * r * 0.5;\n      p.vx = Math.cos(a) * (0.25 + rand() * 0.5); p.vy = Math.sin(a) * (0.25 + rand() * 0.5);\n      p.z = 2 + rand() * 10; p.vz = 14 + rand() * 26;\n      p.r = 3 + rand() * 5; p.life = 0; p.max = 0.7 + rand() * 0.6;\n      p.shade = 0.85 + rand() * 0.25;\n    }\n  }\n  function ring(i, j, rgb) {\n    const r = rings.find(o => !o.on) || rings[0];\n    r.on = true; r.i = i; r.j = j; r.t = 0; r.rgb = rgb;\n  }\n\n  /* ================================================================\n     Stats\n     ================================================================ */\n  let lastPop = -1, lastHappy = -1;\n  function recount(silent) {\n    let pop = 0, sum = 0, weight = 0, homes = 0;\n    for (let j = 0; j < N; j++) {\n      for (let i = 0; i < N; i++) {\n        const t = grid[IDX(i, j)];\n        if (t !== HOUSE && t !== TOWER) continue;\n        homes++;\n        const v = vari[IDX(i, j)];\n        const res = t === HOUSE ? 3 + (v % 3) : 18 + (v % 4) * 6;\n        let h = 52, parks = 0, trees = 0, water = false, towers = 0;\n        for (let dj = -2; dj <= 2; dj++) {\n          for (let di = -2; di <= 2; di++) {\n            if (!di && !dj) continue;\n            const n = at(i + di, j + dj);\n            const near = Math.abs(di) <= 1 && Math.abs(dj) <= 1;\n            if (n === PARK) parks++;\n            if (n === TREE && near) trees++;\n            if (n === WATER) water = true;\n            if (n === TOWER && near) towers++;\n          }\n        }\n        h += Math.min(3, parks) * 11 + Math.min(4, trees) * 3.5 + (water ? 6 : 0);\n        h += roadMask(i, j) ? 5 : -14;\n        if (t === HOUSE) h -= towers * 4;\n        h = clamp(h, 0, 100);\n        pop += res; sum += h * res; weight += res;\n      }\n    }\n    const happy = weight ? Math.round(sum / weight) : -1;\n    popEl.textContent = pop.toLocaleString('en-US');\n    happyEl.textContent = happy < 0 ? '—' : happy + '%';\n    happyBar.style.width = (happy < 0 ? 0 : happy) + '%';\n    // the face: a frown below 45, a grin above 75\n    const m = happy < 0 ? 0.5 : happy / 100;\n    const curve = lerp(-5, 7, m);\n    mouthEl.setAttribute('d', 'M13 ' + (25 - curve * 0.3).toFixed(1) + ' Q20 ' + (25 + curve).toFixed(1) + ' 27 ' + (25 - curve * 0.3).toFixed(1));\n    if (!silent && (pop !== lastPop || happy !== lastHappy)) {\n      bubbleEl.classList.remove('pop');\n      void bubbleEl.offsetWidth;\n      bubbleEl.classList.add('pop');\n    }\n    lastPop = pop; lastHappy = happy;\n    return homes;\n  }\n\n  /* ================================================================\n     Sound (Web Audio, after a gesture, with a toggle)\n     ================================================================ */\n  let soundOn = store.get('pocket-metropolis-sound') !== 'off';\n  let actx = null, master = null;\n  function ensureAudio() {\n    if (!soundOn) return;\n    if (!actx) {\n      try {\n        const AC = window.AudioContext || window.webkitAudioContext;\n        if (!AC) return;\n        actx = new AC();\n        master = actx.createGain();\n        master.gain.value = 0.35;\n        master.connect(actx.destination);\n      } catch (e) { actx = null; return; }\n    }\n    if (actx.state === 'suspended') actx.resume().catch(() => {});\n  }\n  function blip(type) {\n    if (!soundOn || !actx || actx.state !== 'running') return;\n    const t = actx.currentTime + 0.005;\n    if (type === 'dust') {\n      const len = Math.floor(actx.sampleRate * 0.35);\n      const buf = actx.createBuffer(1, len, actx.sampleRate);\n      const d = buf.getChannelData(0);\n      for (let q = 0; q < len; q++) d[q] = (Math.random() * 2 - 1) * Math.pow(1 - q / len, 2.5);\n      const src = actx.createBufferSource();\n      src.buffer = buf;\n      const f = actx.createBiquadFilter();\n      f.type = 'lowpass'; f.frequency.value = 900;\n      const g = actx.createGain(); g.gain.value = 0.5;\n      src.connect(f); f.connect(g); g.connect(master);\n      src.start(t);\n      return;\n    }\n    const notes = { 3: 523.25, 4: 392, 5: 659.25, 6: 587.33, 2: 440, 1: 349.23 };\n    const base = notes[type] || 523.25;\n    for (let q = 0; q < 2; q++) {\n      const o = actx.createOscillator();\n      o.type = q ? 'sine' : 'triangle';\n      o.frequency.setValueAtTime(base * (q ? 2 : 1) * 0.8, t);\n      o.frequency.exponentialRampToValueAtTime(base * (q ? 2 : 1), t + 0.06);\n      const g = actx.createGain();\n      g.gain.setValueAtTime(0.0001, t);\n      g.gain.exponentialRampToValueAtTime(q ? 0.08 : 0.22, t + 0.012);\n      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.28);\n      o.connect(g); g.connect(master);\n      o.start(t); o.stop(t + 0.3);\n    }\n  }\n\n  /* ================================================================\n     Building actions\n     ================================================================ */\n  let tool = 'house';\n  function announce(msg) { statusEl.textContent = msg; }\n  let toastTimer = 0;\n  function toast(msg) {\n    toastEl.textContent = msg;\n    toastEl.classList.add('show');\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(() => toastEl.classList.remove('show'), 1600);\n  }\n\n  function place(i, j, type) {\n    const k = IDX(i, j);\n    const prev = grid[k];\n    if (type === EMPTY) {\n      if (prev === EMPTY) return;\n      grid[k] = EMPTY;\n      born[k] = 0;\n      puff(i, j, reduced ? 4 : 16);\n      blip('dust');\n      announce('Bulldozed the ' + TYPE_NAME[prev] + '.');\n    } else {\n      if (prev === type) {\n        // tapping the same thing again gives it a fresh look\n        vari[k] = (vari[k] + 1 + Math.floor(rand() * 5)) % 26;\n      } else {\n        if (prev !== EMPTY) puff(i, j, reduced ? 3 : 8);\n        grid[k] = type;\n        vari[k] = Math.floor(rand() * 26);\n      }\n      born[k] = reduced ? 0 : performance.now();\n      ring(i, j, type === WATER ? C.foam : C.trim);\n      blip(type);\n      announce('Placed a ' + TYPE_NAME[type] + ' at column ' + (i + 1) + ', row ' + (j + 1) + '.');\n    }\n    rebuildLife();\n    recount(false);\n    saveSoon();\n  }\n\n  /* ================================================================\n     Rendering\n     ================================================================ */\n  let stars = [];\n  function makeStars() {\n    stars = [];\n    const n = Math.round(W * H / 9000);\n    for (let q = 0; q < n; q++) stars.push([rand() * W, rand() * H * 0.62, 0.4 + rand() * 1.1, rand() * 6.28]);\n  }\n  const clouds = [];\n  for (let q = 0; q < 6; q++) clouds.push({ x: rand(), y: 0.06 + rand() * 0.34, s: 0.6 + rand() * 0.8, v: 0.004 + rand() * 0.006 });\n\n  const glows = [];     // flat list: x, y, radius, alpha (world px)\n  const lampGlows = []; // x, y, alpha (world px) — ground pools\n\n  function drawSky(now) {\n    const g = ctx.createLinearGradient(0, 0, 0, H);\n    const T = light.skyTop, L = light.skyLow;\n    g.addColorStop(0, 'rgb(' + (T[0] | 0) + ',' + (T[1] | 0) + ',' + (T[2] | 0) + ')');\n    g.addColorStop(0.72, 'rgb(' + (L[0] | 0) + ',' + (L[1] | 0) + ',' + (L[2] | 0) + ')');\n    g.addColorStop(1, 'rgb(' + (L[0] * 0.96 | 0) + ',' + (L[1] * 0.97 | 0) + ',' + (L[2] * 0.95 | 0) + ')');\n    ctx.fillStyle = g;\n    ctx.fillRect(0, 0, W, H);\n    // stars\n    const n = light.night;\n    if (n > 0.02) {\n      for (const s of stars) {\n        const tw = 0.55 + 0.45 * Math.sin(now * 0.002 + s[3]);\n        ctx.fillStyle = 'rgba(255,250,235,' + (n * tw * 0.9).toFixed(3) + ')';\n        ctx.fillRect(s[0], s[1], s[2], s[2]);\n      }\n    }\n    // sun and moon ride the same arc\n    const ang = (timeOfDay - 0.25) * Math.PI * 2;\n    const ax = W * 0.44, ay = Math.min(H * 0.55, W * 0.5), base = Math.min(H * 0.7, W * 0.9);\n    const cx = W / 2 - Math.cos(ang) * ax, cy = base - Math.sin(ang) * ay;\n    if (light.sunUp > -0.2) {\n      const a = clamp((light.sunUp + 0.2) * 3, 0, 1);\n      const sg = ctx.createRadialGradient(cx, cy, 0, cx, cy, 90);\n      sg.addColorStop(0, 'rgba(255,244,214,' + (0.9 * a).toFixed(3) + ')');\n      sg.addColorStop(0.25, 'rgba(255,226,160,' + (0.55 * a).toFixed(3) + ')');\n      sg.addColorStop(1, 'rgba(255,214,170,0)');\n      ctx.fillStyle = sg;\n      ctx.beginPath(); ctx.arc(cx, cy, 90, 0, Math.PI * 2); ctx.fill();\n      ctx.fillStyle = 'rgba(255,248,226,' + a.toFixed(3) + ')';\n      ctx.beginPath(); ctx.arc(cx, cy, 20, 0, Math.PI * 2); ctx.fill();\n    }\n    const mx = W / 2 + Math.cos(ang) * ax, my = base + Math.sin(ang) * ay;\n    if (light.sunUp < 0.2) {\n      const a = clamp((0.2 - light.sunUp) * 3, 0, 1);\n      ctx.fillStyle = 'rgba(255,250,235,' + (0.95 * a).toFixed(3) + ')';\n      ctx.beginPath(); ctx.arc(mx, my, 15, 0, Math.PI * 2); ctx.fill();\n      ctx.fillStyle = 'rgba(' + (light.skyTop[0] | 0) + ',' + (light.skyTop[1] | 0) + ',' + (light.skyTop[2] | 0) + ',' + a.toFixed(3) + ')';\n      ctx.beginPath(); ctx.arc(mx + 6, my - 4, 13, 0, Math.PI * 2); ctx.fill();\n    }\n    // pastel clouds\n    for (const c of clouds) {\n      const x = ((c.x + now * 0.00001 * c.v * 60) % 1.3 - 0.15) * W, y = c.y * H, s = c.s * Math.min(1.2, W / 900 + 0.4);\n      ctx.fillStyle = lit([255, 255, 255], 1, (0.7 - n * 0.45).toFixed(3));\n      ctx.beginPath();\n      ctx.ellipse(x, y, 60 * s, 18 * s, 0, 0, Math.PI * 2);\n      ctx.ellipse(x - 30 * s, y + 2 * s, 32 * s, 16 * s, 0, 0, Math.PI * 2);\n      ctx.ellipse(x + 20 * s, y - 12 * s, 34 * s, 22 * s, 0, 0, Math.PI * 2);\n      ctx.ellipse(x - 16 * s, y - 10 * s, 24 * s, 17 * s, 0, 0, Math.PI * 2);\n      ctx.fill();\n    }\n  }\n\n  function drawBoardBase() {\n    const depth = 26;\n    // floating island shadow\n    ctx.save();\n    ctx.translate(0, N * THH * 2 + 58);\n    ctx.scale(1, 0.09);\n    const sg = ctx.createRadialGradient(0, 0, 0, 0, 0, N * TWH * 0.85);\n    sg.addColorStop(0, 'rgba(60,50,90,' + (0.2 + light.night * 0.06).toFixed(3) + ')');\n    sg.addColorStop(0.6, 'rgba(60,50,90,' + (0.08 + light.night * 0.03).toFixed(3) + ')');\n    sg.addColorStop(1, 'rgba(60,50,90,0)');\n    ctx.fillStyle = sg;\n    ctx.beginPath();\n    ctx.arc(0, 0, N * TWH * 0.85, 0, Math.PI * 2);\n    ctx.fill();\n    ctx.restore();\n    // front-left side (y = N)\n    pathQuad(0, N, 0, N, N, 0, N, N, -depth, 0, N, -depth);\n    let g = ctx.createLinearGradient(0, PY(0, N, 0), 0, PY(0, N, -depth) + 30);\n    g.addColorStop(0, lit(C.soilTop, 0.95));\n    g.addColorStop(0.35, lit(C.soil, 0.9));\n    g.addColorStop(1, lit(C.soilDeep, 0.78));\n    ctx.fillStyle = g;\n    ctx.fill();\n    // front-right side (x = N)\n    pathQuad(N, N, 0, N, 0, 0, N, 0, -depth, N, N, -depth);\n    g = ctx.createLinearGradient(0, PY(N, 0, 0), 0, PY(N, N, -depth) + 30);\n    g.addColorStop(0, lit(C.soilTop, 0.8));\n    g.addColorStop(0.35, lit(C.soil, 0.74));\n    g.addColorStop(1, lit(C.soilDeep, 0.64));\n    ctx.fillStyle = g;\n    ctx.fill();\n    // strata lines and pebbles\n    ctx.strokeStyle = lit(C.soilDeep, 0.85, 0.55);\n    ctx.lineWidth = 1.2;\n    for (const z of [-10, -18]) {\n      ctx.beginPath();\n      ctx.moveTo(PX(0, N), PY(0, N, z));\n      for (let s = 1; s <= 12; s++) ctx.lineTo(PX(s, N), PY(s, N, z + Math.sin(s * 1.7 + z) * 1.5));\n      for (let s = 11; s >= 0; s--) ctx.lineTo(PX(N, s), PY(N, s, z + Math.sin(s * 2.1 - z) * 1.5));\n      ctx.stroke();\n    }\n    ctx.fillStyle = lit(C.soilTop, 1.02, 0.8);\n    for (let s = 0; s < 22; s++) {\n      const u = hash(s, 3, 9) * N, zz = -6 - hash(s, 5, 1) * 18;\n      const onLeft = s % 2 === 0;\n      const x = onLeft ? PX(u, N) : PX(N, u), y = onLeft ? PY(u, N, zz) : PY(N, u, zz);\n      ctx.beginPath(); ctx.ellipse(x, y, 2.2, 1.3, 0, 0, Math.PI * 2); ctx.fill();\n    }\n    // grassy lip\n    ctx.beginPath();\n    ctx.moveTo(PX(0, N), PY(0, N, 0));\n    ctx.lineTo(PX(N, N), PY(N, N, 0));\n    ctx.lineTo(PX(N, 0), PY(N, 0, 0));\n    ctx.lineTo(PX(N, 0), PY(N, 0, -3));\n    ctx.lineTo(PX(N, N), PY(N, N, -3));\n    ctx.lineTo(PX(0, N), PY(0, N, -3));\n    ctx.closePath();\n    ctx.fillStyle = lit(C.grassDeep, 0.9);\n    ctx.fill();\n  }\n\n  function drawGround(i, j, now) {\n    const k = IDX(i, j), t = grid[k], v = vari[k];\n    if (t === WATER) {\n      const e = 0.07;\n      diamond(i, j, i + 1, j + 1, 0);\n      ctx.fillStyle = lit(C.sand, 1);\n      ctx.fill();\n      const x0 = i + (at(i - 1, j) === WATER ? 0 : e), x1 = i + 1 - (at(i + 1, j) === WATER ? 0 : e);\n      const y0 = j + (at(i, j - 1) === WATER ? 0 : e), y1 = j + 1 - (at(i, j + 1) === WATER ? 0 : e);\n      diamond(x0, y0, x1, y1, -2);\n      const g = ctx.createLinearGradient(0, PY(i, j, 0), 0, PY(i + 1, j + 1, 0));\n      g.addColorStop(0, lit(C.water, 1.04));\n      g.addColorStop(1, lit(C.waterDeep, 0.98));\n      ctx.fillStyle = g;\n      ctx.fill();\n      // drifting glints\n      ctx.strokeStyle = lit(C.foam, 1, 0.75);\n      ctx.lineWidth = 1.2;\n      ctx.lineCap = 'round';\n      for (let q = 0; q < 2; q++) {\n        const ph = (now * 0.00012 * (reduced ? 0.3 : 1) + hash(i, j, q)) % 1;\n        const gx = i + 0.2 + ph * 0.6, gy = j + 0.25 + q * 0.45 + Math.sin(ph * 6.28) * 0.05;\n        const a = Math.sin(ph * Math.PI);\n        ctx.globalAlpha = a;\n        ctx.beginPath();\n        ctx.moveTo(PX(gx - 0.1, gy), PY(gx - 0.1, gy, -2));\n        ctx.quadraticCurveTo(PX(gx, gy - 0.05), PY(gx, gy - 0.05, -2), PX(gx + 0.1, gy), PY(gx + 0.1, gy, -2));\n        ctx.stroke();\n      }\n      ctx.globalAlpha = 1;\n      return;\n    }\n    if (t === ROAD) { drawRoad(i, j); return; }\n    const base = t === PARK ? C.lawn : ((i + j) % 2 ? C.grass : [C.grass[0] - 5, C.grass[1] - 3, C.grass[2] - 6]);\n    diamond(i, j, i + 1, j + 1, 0);\n    ctx.fillStyle = lit(base, 1);\n    ctx.fill();\n    ctx.strokeStyle = lit(C.grassDeep, 1, 0.35);\n    ctx.lineWidth = 0.6;\n    ctx.stroke();\n    if (t === EMPTY || t === TREE) {\n      // tufts\n      ctx.strokeStyle = lit(C.grassDeep, 0.92, 0.9);\n      ctx.lineWidth = 1;\n      for (let q = 0; q < 3; q++) {\n        const gx = i + 0.2 + hash(i, j, q) * 0.6, gy = j + 0.2 + hash(j, i, q + 5) * 0.6;\n        const sx = PX(gx, gy), sy = PY(gx, gy, 0);\n        ctx.beginPath();\n        ctx.moveTo(sx - 2, sy); ctx.lineTo(sx - 1, sy - 3);\n        ctx.moveTo(sx, sy); ctx.lineTo(sx, sy - 4);\n        ctx.moveTo(sx + 2, sy); ctx.lineTo(sx + 1, sy - 3);\n        ctx.stroke();\n      }\n      if (t === EMPTY && hash(i, j, 77) < 0.3) {\n        const gx = i + 0.3 + hash(i, j, 78) * 0.4, gy = j + 0.3 + hash(i, j, 79) * 0.4;\n        ctx.fillStyle = lit(C.flowers[v % 4], 1);\n        ctx.beginPath(); ctx.arc(PX(gx, gy), PY(gx, gy, 0) - 1, 1.6, 0, Math.PI * 2); ctx.fill();\n      }\n    }\n    if (t === PARK) drawParkGround(i, j, v);\n  }\n\n  function drawParkGround(i, j, v) {\n    // a winding path through the lawn\n    ctx.strokeStyle = lit(C.path, 1);\n    ctx.lineWidth = 5;\n    ctx.lineCap = 'round';\n    ctx.beginPath();\n    const flip = v % 2;\n    const a = flip ? [i, j + 0.5] : [i + 0.5, j], b = flip ? [i + 1, j + 0.5] : [i + 0.5, j + 1];\n    ctx.moveTo(PX(a[0], a[1]), PY(a[0], a[1], 0));\n    ctx.bezierCurveTo(PX(i + 0.3, j + 0.7), PY(i + 0.3, j + 0.7, 0), PX(i + 0.7, j + 0.3), PY(i + 0.7, j + 0.3, 0), PX(b[0], b[1]), PY(b[0], b[1], 0));\n    ctx.stroke();\n    // a pond or a fountain\n    const px = i + 0.68, py = j + 0.62;\n    ctx.fillStyle = lit(C.path, 0.95);\n    ctx.beginPath(); ctx.ellipse(PX(px, py), PY(px, py, 0), 10.5, 5.6, 0, 0, Math.PI * 2); ctx.fill();\n    ctx.fillStyle = lit(C.water, 1.03);\n    ctx.beginPath(); ctx.ellipse(PX(px, py), PY(px, py, 0) - 0.5, 8, 4.1, 0, 0, Math.PI * 2); ctx.fill();\n    // flowerbeds\n    for (let q = 0; q < 7; q++) {\n      const fx = i + 0.12 + hash(i, j, q + 30) * 0.3, fy = j + 0.12 + hash(i, j, q + 40) * 0.35;\n      ctx.fillStyle = lit(C.flowers[(q + v) % 4], 1);\n      ctx.beginPath(); ctx.arc(PX(fx, fy), PY(fx, fy, 0) - 1, 1.5, 0, Math.PI * 2); ctx.fill();\n    }\n  }\n\n  function drawRoad(i, j) {\n    const m = roadMask(i, j);\n    diamond(i, j, i + 1, j + 1, 0);\n    ctx.fillStyle = lit(C.road, 1);\n    ctx.fill();\n    // sidewalks on the sides that do not continue\n    const w = 0.13;\n    ctx.fillStyle = lit(C.walk, 1.02);\n    if (!(m & 1)) { diamond(i + 1 - w, j, i + 1, j + 1, 0.8); ctx.fill(); }\n    if (!(m & 4)) { diamond(i, j, i + w, j + 1, 0.8); ctx.fill(); }\n    if (!(m & 2)) { diamond(i, j + 1 - w, i + 1, j + 1, 0.8); ctx.fill(); }\n    if (!(m & 8)) { diamond(i, j, i + 1, j + w, 0.8); ctx.fill(); }\n    // corner curbs where two sidewalks do not meet\n    ctx.fillStyle = lit(C.walk, 1.02);\n    if ((m & 1) && (m & 2)) { diamond(i + 1 - w, j + 1 - w, i + 1, j + 1, 0.8); ctx.fill(); }\n    if ((m & 1) && (m & 8)) { diamond(i + 1 - w, j, i + 1, j + w, 0.8); ctx.fill(); }\n    if ((m & 4) && (m & 2)) { diamond(i, j + 1 - w, i + w, j + 1, 0.8); ctx.fill(); }\n    if ((m & 4) && (m & 8)) { diamond(i, j, i + w, j + w, 0.8); ctx.fill(); }\n    const cnt = (m & 1 ? 1 : 0) + (m & 2 ? 1 : 0) + (m & 4 ? 1 : 0) + (m & 8 ? 1 : 0);\n    ctx.lineCap = 'butt';\n    if (cnt >= 3) {\n      // zebra crossings on each approach\n      ctx.fillStyle = lit(C.paint, 1, 0.9);\n      const dirs = [[1, 1, 0], [2, 0, 1], [4, -1, 0], [8, 0, -1]];\n      for (const d of dirs) {\n        if (!(m & d[0])) continue;\n        for (let s = 0; s < 4; s++) {\n          const o = 0.28 + s * 0.13;\n          if (d[1]) {\n            const x = d[1] > 0 ? i + 0.82 : i + 0.1;\n            diamond(x, j + o - 0.04, x + 0.08, j + o + 0.04, 0.2);\n          } else {\n            const y = d[2] > 0 ? j + 0.82 : j + 0.1;\n            diamond(i + o - 0.04, y, i + o + 0.04, y + 0.08, 0.2);\n          }\n          ctx.fill();\n        }\n      }\n    } else {\n      ctx.strokeStyle = lit(C.paint, 1, 0.95);\n      ctx.lineWidth = 1.4;\n      ctx.setLineDash([4, 4]);\n      const cx = i + 0.5, cy = j + 0.5;\n      const ends = [];\n      if (m & 1) ends.push([i + 1, cy]);\n      if (m & 4) ends.push([i, cy]);\n      if (m & 2) ends.push([cx, j + 1]);\n      if (m & 8) ends.push([cx, j]);\n      ctx.beginPath();\n      if (ends.length === 0) {\n        ctx.setLineDash([]);\n        ctx.ellipse(PX(cx, cy), PY(cx, cy, 0), 9, 4.6, 0, 0, Math.PI * 2);\n      } else {\n        for (const e of ends) {\n          ctx.moveTo(PX(cx, cy), PY(cx, cy, 0));\n          ctx.lineTo(PX(e[0], e[1]), PY(e[0], e[1], 0));\n        }\n      }\n      ctx.stroke();\n      ctx.setLineDash([]);\n    }\n  }\n\n  function hasLamp(i, j) { return grid[IDX(i, j)] === ROAD && (i * 5 + j * 3) % 4 === 0; }\n\n  /* shadows fall away from the sun onto the ground */\n  function drawShadows() {\n    const sh = clamp(1.25 - Math.max(0, light.sunUp) * 1.1, 0.25, 1.4);\n    const sx = light.sunX * 0.55 * sh, sy = -light.sunX * 0.2 * sh + 0.25 * sh;\n    const alpha = 0.16 * clamp(light.sunUp * 3, 0.25, 1) * (1 - light.night * 0.6);\n    ctx.fillStyle = 'rgba(56,48,92,' + alpha.toFixed(3) + ')';\n    for (let j = 0; j < N; j++) {\n      for (let i = 0; i < N; i++) {\n        const t = grid[IDX(i, j)];\n        let h = 0, inset = 0.14;\n        if (t === HOUSE) { h = 38; inset = 0.17; }\n        else if (t === TOWER) { h = 48 + (vari[IDX(i, j)] % 4) * 18; inset = 0.14; }\n        else if (t === TREE) { h = 30; inset = 0.3; }\n        else continue;\n        const k = h / 40;\n        const x0 = i + inset, x1 = i + 1 - inset, y0 = j + inset, y1 = j + 1 - inset;\n        const ox = sx * k, oy = sy * k;\n        ctx.beginPath();\n        ctx.moveTo(PX(x0, y0), PY(x0, y0, 0));\n        ctx.lineTo(PX(x1, y0), PY(x1, y0, 0));\n        ctx.lineTo(PX(x1 + ox, y0 + oy), PY(x1 + ox, y0 + oy, 0));\n        ctx.lineTo(PX(x1 + ox, y1 + oy), PY(x1 + ox, y1 + oy, 0));\n        ctx.lineTo(PX(x0 + ox, y1 + oy), PY(x0 + ox, y1 + oy, 0));\n        ctx.lineTo(PX(x0, y1), PY(x0, y1, 0));\n        ctx.closePath();\n        ctx.fill();\n      }\n    }\n    // soft contact shadow (ambient occlusion) hugging every building base\n    ctx.fillStyle = 'rgba(56,48,92,0.12)';\n    for (let j = 0; j < N; j++) {\n      for (let i = 0; i < N; i++) {\n        const t = grid[IDX(i, j)];\n        if (t !== HOUSE && t !== TOWER) continue;\n        const e = t === HOUSE ? 0.12 : 0.09;\n        diamond(i + e, j + e, i + 1 - e, j + 1 - e, 0);\n        ctx.fill();\n      }\n    }\n  }\n\n  /* squash-and-stretch as a building pops in */\n  function popScale(k, now) {\n    const b = born[k];\n    if (!b) return 1;\n    const p = (now - b) / 650;\n    if (p < 0) return 0;\n    if (p >= 1) { born[k] = 0; return 1; }\n    const rise = Math.min(1, p * 3.2);\n    return rise * (1 + 0.28 * Math.sin(p * Math.PI * 3.2) * (1 - p));\n  }\n\n  function withPop(i, j, s, fn) {\n    if (s === 1) { fn(); return; }\n    if (s <= 0) return;\n    const ax = PX(i + 0.5, j + 0.5), ay = PY(i + 0.5, j + 0.5, 0);\n    const ws = 1 / Math.sqrt(Math.max(0.3, s));\n    ctx.save();\n    ctx.translate(ax, ay);\n    ctx.scale(ws, s);\n    ctx.translate(-ax, -ay);\n    fn();\n    ctx.restore();\n  }\n\n  function drawHouse(i, j, v) {\n    const e = 0.18;\n    const x0 = i + e, x1 = i + 1 - e, y0 = j + e, y1 = j + 1 - e;\n    const wall = C.walls[v % 4], roof = C.roofs[(v >> 2) % C.roofs.length];\n    const h = 20 + (v % 3) * 3;\n    box(x0, y0, x1, y1, 0, h, wall);\n    // door and windows\n    const midx = (x0 + x1) / 2;\n    pathQuad(midx - 0.07, y1, 0, midx + 0.07, y1, 0, midx + 0.07, y1, 11, midx - 0.07, y1, 11);\n    ctx.fillStyle = lit(C.door, 0.9);\n    ctx.fill();\n    winQuad(x0 + 0.08, y1, x0 + 0.2, y1, 7, 14, hash(i, j, 1) < 0.8);\n    winQuad(x1 - 0.2, y1, x1 - 0.08, y1, 7, 14, hash(i, j, 2) < 0.6);\n    winQuad(x1, y1 - 0.12, x1, y1 - 0.26, 7, 14, hash(i, j, 3) < 0.7);\n    winQuad(x1, y0 + 0.26, x1, y0 + 0.12, 7, 14, hash(i, j, 4) < 0.5);\n    // gabled roof, ridge running along x\n    const ov = 0.05, rz = h + 14;\n    const ym = (y0 + y1) / 2;\n    // left roof slope (towards +y)\n    pathQuad(x0 - ov, y1 + ov, h, x1 + ov, y1 + ov, h, x1 + ov, ym, rz, x0 - ov, ym, rz);\n    ctx.fillStyle = lit(roof, 0.95 - 0.06 * light.sunX);\n    ctx.fill();\n    // right gable end (x = x1)\n    ctx.beginPath();\n    ctx.moveTo(PX(x1, y1), PY(x1, y1, h));\n    ctx.lineTo(PX(x1, y0), PY(x1, y0, h));\n    ctx.lineTo(PX(x1, ym), PY(x1, ym, rz - 1));\n    ctx.closePath();\n    ctx.fillStyle = lit(wall, 0.72 + 0.06 * light.sunX);\n    ctx.fill();\n    // back slope peeking + ridge line\n    pathQuad(x1 + ov, y0 - ov, h, x1 + ov, ym, rz, x1 + ov, y1 + ov, h, x1 + ov, y1 + ov, h);\n    ctx.fillStyle = lit(roof, 0.7);\n    ctx.fill();\n    ctx.beginPath();\n    ctx.moveTo(PX(x0 - ov, ym), PY(x0 - ov, ym, rz));\n    ctx.lineTo(PX(x1 + ov, ym), PY(x1 + ov, ym, rz));\n    ctx.strokeStyle = lit(roof, 1.18);\n    ctx.lineWidth = 1.4;\n    ctx.stroke();\n    // roof eave shade\n    ctx.beginPath();\n    ctx.moveTo(PX(x0 - ov, y1 + ov), PY(x0 - ov, y1 + ov, h));\n    ctx.lineTo(PX(x1 + ov, y1 + ov), PY(x1 + ov, y1 + ov, h));\n    ctx.strokeStyle = lit(roof, 0.62);\n    ctx.lineWidth = 1.2;\n    ctx.stroke();\n    // chimney\n    if (v % 2 === 0) {\n      const cxx = x0 + 0.12;\n      box(cxx, ym - 0.12, cxx + 0.1, ym - 0.02, rz - 8, rz + 5, C.walls[(v + 1) % 4]);\n    }\n  }\n\n  function drawTower(i, j, v) {\n    const e = 0.14;\n    const x0 = i + e, x1 = i + 1 - e, y0 = j + e, y1 = j + 1 - e;\n    const col = C.walls[(v + 2) % 4];\n    const floors = 4 + (v % 4) * 2;\n    const h = floors * 9 + 12;\n    box(x0, y0, x1, y1, 0, h, col, { soft: 1, top: [col[0] * 1.02, col[1] * 1.02, col[2] * 1.02] });\n    // lobby band\n    pathQuad(x0, y1, 0, x1, y1, 0, x1, y1, 8, x0, y1, 8);\n    ctx.fillStyle = lit(C.trim, 0.9);\n    ctx.fill();\n    pathQuad(x1, y1, 0, x1, y0, 0, x1, y0, 8, x1, y1, 8);\n    ctx.fillStyle = lit(C.trim, 0.78);\n    ctx.fill();\n    windowsLeft(x0 + 0.04, x1 - 0.04, y1, 11, h - 3, 2, floors, i * 31 + j * 7 + v, 0.15, 4.4);\n    windowsRight(y0 + 0.04, y1 - 0.04, x1, 11, h - 3, 2, floors, i * 31 + j * 7 + v, 0.15, 4.4);\n    // a pale pilaster between the window columns\n    const mx = (x0 + x1) / 2, my = (y0 + y1) / 2;\n    pathQuad(mx - 0.012, y1, 9, mx + 0.012, y1, 9, mx + 0.012, y1, h, mx - 0.012, y1, h);\n    ctx.fillStyle = lit(C.trim, 0.96, 0.7);\n    ctx.fill();\n    pathQuad(x1, my + 0.012, 9, x1, my - 0.012, 9, x1, my - 0.012, h, x1, my + 0.012, h);\n    ctx.fillStyle = lit(C.trim, 0.86, 0.6);\n    ctx.fill();\n    // cornice\n    box(x0 - 0.03, y0 - 0.03, x1 + 0.03, y1 + 0.03, h, h + 3, C.trim);\n    // rooftop: water tank, garden or antenna\n    const kind = (v >> 1) % 3;\n    if (kind === 0) {\n      box(x0 + 0.12, y0 + 0.12, x0 + 0.34, y0 + 0.34, h + 3, h + 11, C.metal);\n    } else if (kind === 1) {\n      box(x0 + 0.08, y0 + 0.08, x1 - 0.08, y1 - 0.08, h + 3, h + 5, C.leaf[1]);\n      ctx.fillStyle = lit(C.leaf[2], 1.05);\n      ctx.beginPath(); ctx.arc(PX(x0 + 0.3, y0 + 0.3), PY(x0 + 0.3, y0 + 0.3, h + 9), 4.5, 0, Math.PI * 2); ctx.fill();\n    } else {\n      const ax = PX(x0 + 0.3, y0 + 0.3), ay = PY(x0 + 0.3, y0 + 0.3, h + 3);\n      ctx.strokeStyle = lit(C.lamp, 0.9);\n      ctx.lineWidth = 1.2;\n      ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ax, ay - 18); ctx.stroke();\n      const blink = (performance.now() % 1600) < 800 ? 1 : 0.35;\n      ctx.fillStyle = 'rgba(255,120,130,' + (0.5 + 0.5 * blink * (0.4 + light.night * 0.6)).toFixed(3) + ')';\n      ctx.beginPath(); ctx.arc(ax, ay - 19, 1.8, 0, Math.PI * 2); ctx.fill();\n      if (light.night > 0.1) glows.push(ax, ay - 19, 7, 0.4 * light.night * blink);\n    }\n  }\n\n  function drawTree(x, y, s, v) {\n    const sx = PX(x, y), sy = PY(x, y, 0);\n    ctx.fillStyle = lit(C.trunk, 0.9);\n    ctx.beginPath();\n    ctx.roundRect ? ctx.roundRect(sx - 1.6 * s, sy - 12 * s, 3.2 * s, 12 * s, 1.2) : ctx.rect(sx - 1.6 * s, sy - 12 * s, 3.2 * s, 12 * s);\n    ctx.fill();\n    const leaf = C.leaf[v % 3];\n    const sway = reduced ? 0 : Math.sin(performance.now() * 0.0012 + x * 3 + y * 5) * 0.8;\n    const cy = sy - 19 * s;\n    const g = ctx.createRadialGradient(sx - 3 * s + sway, cy - 4 * s, 1, sx + sway, cy, 11 * s);\n    g.addColorStop(0, lit(C.leafHi, 1.02));\n    g.addColorStop(0.55, lit(leaf, 1));\n    g.addColorStop(1, lit(leaf, 0.8));\n    ctx.fillStyle = g;\n    ctx.beginPath();\n    ctx.arc(sx + sway, cy, 10 * s, 0, Math.PI * 2);\n    ctx.arc(sx - 5 * s + sway, cy + 4 * s, 6.5 * s, 0, Math.PI * 2);\n    ctx.arc(sx + 5.5 * s + sway, cy + 3.5 * s, 6.5 * s, 0, Math.PI * 2);\n    ctx.fill();\n  }\n\n  function drawTreesTile(i, j, v) {\n    const n = 1 + (v % 3);\n    const spots = [[0.5, 0.5], [0.3, 0.35], [0.7, 0.62], [0.32, 0.7], [0.7, 0.3]];\n    const order = n === 1 ? [0] : n === 2 ? [1, 2] : [1, 4, 3];\n    for (const q of order) drawTree(i + spots[q][0], j + spots[q][1], n === 1 ? 1.1 : 0.85, v + q);\n  }\n\n  function drawParkThings(i, j, v) {\n    // bench\n    const bx = i + 0.28, by = j + 0.8;\n    box(bx, by, bx + 0.22, by + 0.06, 3, 4.5, C.trunk);\n    box(bx, by - 0.02, bx + 0.22, by, 4.5, 8, C.trunk);\n    // one tree in the corner\n    drawTree(i + 0.25, j + 0.28, 0.85, v + 1);\n    // fountain spray\n    const px = i + 0.68, py = j + 0.62;\n    const sx = PX(px, py), sy = PY(px, py, 0);\n    ctx.fillStyle = lit(C.trim, 0.95);\n    ctx.fillRect(sx - 1.3, sy - 7, 2.6, 7);\n    const t = performance.now() * 0.004;\n    ctx.fillStyle = lit(C.foam, 1, 0.9);\n    for (let q = 0; q < 5; q++) {\n      const a = t + q * 1.26;\n      const r = (q % 2 ? 3.5 : 5) + Math.sin(a * 2) * 0.6;\n      ctx.beginPath(); ctx.arc(sx + Math.cos(a) * r, sy - 6 + Math.abs(Math.sin(a)) * 3 - 3, 1.1, 0, Math.PI * 2); ctx.fill();\n    }\n  }\n\n  function drawLamp(i, j) {\n    const m = roadMask(i, j);\n    // stand on a sidewalk corner\n    const lx = m & 1 ? i + 0.08 : i + 0.92, ly = m & 2 ? j + 0.08 : j + 0.92;\n    const sx = PX(lx, ly), sy = PY(lx, ly, 0);\n    ctx.strokeStyle = lit(C.lamp, 0.9);\n    ctx.lineWidth = 1.5;\n    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(sx, sy - 22); ctx.stroke();\n    const n = light.night;\n    ctx.fillStyle = n > 0.05 ? emit([255, 236, 170], (0.55 + 0.45 * n).toFixed(3)) : lit(C.trim, 0.95);\n    ctx.beginPath(); ctx.arc(sx, sy - 23, 2.6, 0, Math.PI * 2); ctx.fill();\n    if (n > 0.05) {\n      lampGlows.push(sx, sy, n);\n      glows.push(sx, sy - 23, 12, 0.55 * n);\n    }\n  }\n\n  function drawCar(c) {\n    const along = c.dx !== 0;\n    const L = 0.2, Wd = 0.11;\n    const x0 = c.x - (along ? L : Wd), x1 = c.x + (along ? L : Wd);\n    const y0 = c.y - (along ? Wd : L), y1 = c.y + (along ? Wd : L);\n    box(x0, y0, x1, y1, 1.5, 6.5, c.col);\n    const ix = along ? 0.07 : 0.02, iy = along ? 0.02 : 0.07;\n    box(x0 + ix + (c.dx < 0 ? 0.04 : 0), y0 + iy + (c.dy < 0 ? 0.04 : 0), x1 - ix - (c.dx > 0 ? 0.04 : 0), y1 - iy - (c.dy > 0 ? 0.04 : 0), 6.5, 10.5, C.glass, { top: c.col });\n    if (light.night > 0.1) {\n      const hx = c.x + c.dx * 0.26, hy = c.y + c.dy * 0.26;\n      glows.push(PX(hx, hy), PY(hx, hy, 4), 9, 0.5 * light.night);\n    }\n  }\n\n  function drawWalker(w) {\n    const i = w.k % N, j = (w.k / N) | 0;\n    const x = i + w.x, y = j + w.y;\n    const sx = PX(x, y), sy = PY(x, y, 0);\n    const bob = w.wait > 0 ? 0 : Math.abs(Math.sin(w.ph)) * 1.2;\n    ctx.fillStyle = 'rgba(56,48,92,0.18)';\n    ctx.beginPath(); ctx.ellipse(sx, sy, 2.6, 1.2, 0, 0, Math.PI * 2); ctx.fill();\n    ctx.fillStyle = lit(w.col, 1);\n    ctx.beginPath();\n    ctx.roundRect ? ctx.roundRect(sx - 1.7, sy - 7.5 - bob, 3.4, 6, 1.4) : ctx.rect(sx - 1.7, sy - 7.5 - bob, 3.4, 6);\n    ctx.fill();\n    ctx.fillStyle = lit([255, 219, 196], 1);\n    ctx.beginPath(); ctx.arc(sx, sy - 9.4 - bob, 1.9, 0, Math.PI * 2); ctx.fill();\n  }\n\n  /* ---------------- per-frame object list, sorted back to front ---------------- */\n  const drawList = [];\n  function frameScene(now) {\n    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);\n    drawSky(now);\n    ctx.setTransform(DPR * cam.zoom, 0, 0, DPR * cam.zoom, DPR * cam.x, DPR * cam.y);\n    drawBoardBase();\n    glows.length = 0;\n    lampGlows.length = 0;\n    for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) drawGround(i, j, now);\n    // ground rings from new placements\n    for (const r of rings) {\n      if (!r.on) continue;\n      r.t += 1 / 60 * 1.6;\n      if (r.t >= 1) { r.on = false; continue; }\n      const cx = PX(r.i + 0.5, r.j + 0.5), cy = PY(r.i + 0.5, r.j + 0.5, 0);\n      ctx.strokeStyle = emit(r.rgb, (0.9 * (1 - r.t)).toFixed(3));\n      ctx.lineWidth = 2.5 * (1 - r.t) + 0.5;\n      ctx.beginPath(); ctx.ellipse(cx, cy, 10 + 30 * r.t, (10 + 30 * r.t) / 2, 0, 0, Math.PI * 2); ctx.stroke();\n    }\n    drawShadows();\n    // lamp pools on the ground (under everything that stands)\n    drawList.length = 0;\n    for (let j = 0; j < N; j++) {\n      for (let i = 0; i < N; i++) {\n        const t = grid[IDX(i, j)];\n        if (t === HOUSE || t === TOWER || t === TREE || t === PARK) drawList.push([i + j + 1, 0, i, j]);\n        if (hasLamp(i, j)) drawList.push([i + j + 1.9, 3, i, j]);\n      }\n    }\n    for (let q = 0; q < cars.length; q++) drawList.push([cars[q].x + cars[q].y, 1, q, 0]);\n    for (let q = 0; q < walkers.length; q++) {\n      const w = walkers[q];\n      if (grid[w.k] !== PARK) continue;\n      drawList.push([(w.k % N) + ((w.k / N) | 0) + w.x + w.y, 2, q, 0]);\n    }\n    drawList.sort((a, b) => a[0] - b[0]);\n    for (const d of drawList) {\n      if (d[1] === 0) {\n        const i = d[2], j = d[3], k = IDX(i, j), t = grid[k], v = vari[k];\n        const s = popScale(k, now);\n        withPop(i, j, s, () => {\n          if (t === HOUSE) drawHouse(i, j, v);\n          else if (t === TOWER) drawTower(i, j, v);\n          else if (t === TREE) drawTreesTile(i, j, v);\n          else if (t === PARK) drawParkThings(i, j, v);\n        });\n      } else if (d[1] === 1) drawCar(cars[d[2]]);\n      else if (d[1] === 2) drawWalker(walkers[d[2]]);\n      else drawLamp(d[2], d[3]);\n    }\n    // night glows: lamp pools, windows, headlights\n    if (light.night > 0.05) {\n      ctx.globalCompositeOperation = 'lighter';\n      for (let q = 0; q < lampGlows.length; q += 3) {\n        const x = lampGlows[q], y = lampGlows[q + 1], a = lampGlows[q + 2];\n        const g = ctx.createRadialGradient(x, y, 0, x, y, 30);\n        g.addColorStop(0, 'rgba(255,214,140,' + (0.32 * a).toFixed(3) + ')');\n        g.addColorStop(1, 'rgba(255,214,140,0)');\n        ctx.fillStyle = g;\n        ctx.beginPath(); ctx.ellipse(x, y, 30, 15, 0, 0, Math.PI * 2); ctx.fill();\n      }\n      for (let q = 0; q < glows.length; q += 4) {\n        const x = glows[q], y = glows[q + 1], r = glows[q + 2], a = glows[q + 3];\n        const g = ctx.createRadialGradient(x, y, 0, x, y, r);\n        g.addColorStop(0, 'rgba(255,226,160,' + a.toFixed(3) + ')');\n        g.addColorStop(1, 'rgba(255,226,160,0)');\n        ctx.fillStyle = g;\n        ctx.fillRect(x - r, y - r, r * 2, r * 2);\n      }\n      ctx.globalCompositeOperation = 'source-over';\n    }\n    // dust\n    for (const p of puffs) {\n      if (!p.on) continue;\n      const a = 1 - p.life / p.max;\n      ctx.fillStyle = lit([236, 226, 210], p.shade, (0.85 * a).toFixed(3));\n      ctx.beginPath();\n      ctx.arc(PX(p.x, p.y), PY(p.x, p.y, p.z), p.r * (1 + p.life * 1.8), 0, Math.PI * 2);\n      ctx.fill();\n    }\n    drawCursor(now);\n  }\n\n  /* hover / keyboard cursor and a ghost preview of the tool */\n  const hover = { i: -1, j: -1, show: false };\n  const kbd = { i: 5, j: 5, show: false };\n  function drawCursor(now) {\n    const c = hover.show ? hover : kbd.show ? kbd : null;\n    if (!c || c.i < 0) return;\n    const i = c.i, j = c.j;\n    const pulse = 0.6 + 0.4 * Math.sin(now * 0.006);\n    diamond(i, j, i + 1, j + 1, 0.5);\n    ctx.lineWidth = 2 / cam.zoom + 1;\n    ctx.setLineDash([5, 4]);\n    ctx.lineDashOffset = -now * 0.02;\n    ctx.strokeStyle = tool === 'bulldoze' ? 'rgba(240,110,100,' + pulse.toFixed(3) + ')' : 'rgba(255,255,255,' + (0.7 + 0.3 * pulse).toFixed(3) + ')';\n    ctx.stroke();\n    ctx.setLineDash([]);\n    const t = TOOL_TYPE[tool];\n    if (t !== EMPTY && grid[IDX(i, j)] !== t) {\n      ctx.globalAlpha = 0.5;\n      const v = (i * 7 + j * 13) % 26;\n      if (t === HOUSE) drawHouse(i, j, v);\n      else if (t === TOWER) drawTower(i, j, v);\n      else if (t === TREE) drawTreesTile(i, j, v);\n      else if (t === PARK || t === ROAD || t === WATER) {\n        diamond(i, j, i + 1, j + 1, 1);\n        ctx.fillStyle = lit(t === PARK ? C.lawn : t === ROAD ? C.road : C.water, 1);\n        ctx.fill();\n      }\n      ctx.globalAlpha = 1;\n    }\n  }\n\n  /* ================================================================\n     Loop\n     ================================================================ */\n  let last = 0, raf = 0, hudTimer = 0;\n  function tick(now) {\n    raf = requestAnimationFrame(tick);\n    const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;\n    last = now;\n    if (!paused) {\n      timeOfDay += dt * clockSpeed * (reduced ? 0.5 : 1) / DAY_SECONDS;\n      if (timeOfDay >= 1) { timeOfDay -= 1; dayCount++; }\n    }\n    updateLight();\n    updateCars(dt);\n    updateWalkers(dt);\n    for (const p of puffs) {\n      if (!p.on) continue;\n      p.life += dt;\n      if (p.life >= p.max) { p.on = false; continue; }\n      p.x += p.vx * dt * 0.6; p.y += p.vy * dt * 0.6; p.z += p.vz * dt; p.vz *= 0.94;\n    }\n    frameScene(now);\n    hudTimer -= dt;\n    if (hudTimer <= 0) { hudTimer = 0.25; updateClock(); }\n  }\n  function updateClock() {\n    const mins = Math.floor(timeOfDay * 24 * 60);\n    const hh = Math.floor(mins / 60), mm = mins % 60;\n    const txt = String(hh).padStart(2, '0') + ':' + String(Math.floor(mm / 5) * 5).padStart(2, '0');\n    if (clockEl.firstChild.nodeValue !== txt) clockEl.firstChild.nodeValue = txt;\n    const sm = clockEl.querySelector('small');\n    const d = 'Day ' + dayCount;\n    if (sm.textContent !== d) sm.textContent = d;\n    dialHand.setAttribute('transform', 'rotate(' + ((timeOfDay - 0.5) * 360).toFixed(1) + ' 15 15)');\n  }\n  function start() { if (!raf) { last = 0; raf = requestAnimationFrame(tick); } }\n  function stop() { if (raf) { cancelAnimationFrame(raf); raf = 0; } }\n  document.addEventListener('visibilitychange', () => { if (document.hidden) { stop(); save(); } else start(); });\n\n  /* ================================================================\n     Input: tap to build, right-click / long-press to bulldoze,\n     drag to pan, wheel / pinch to zoom\n     ================================================================ */\n  const pointers = new Map();\n  let gesture = null; // { mode: 'tap'|'pan'|'pinch', ... }\n  let longTimer = 0;\n\n  function selectTool(name, speak) {\n    tool = name;\n    for (const b of toolBtns) b.setAttribute('aria-pressed', b.dataset.tool === name ? 'true' : 'false');\n    if (speak) announce(name === 'bulldoze' ? 'Bulldozer selected.' : name.charAt(0).toUpperCase() + name.slice(1) + ' selected.');\n  }\n\n  world.addEventListener('pointerdown', (e) => {\n    ensureAudio();\n    try { world.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }\n    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });\n    if (pointers.size === 2) {\n      clearTimeout(longTimer);\n      const [a, b] = Array.from(pointers.values());\n      gesture = { mode: 'pinch', d: Math.hypot(a.x - b.x, a.y - b.y), mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2 };\n      return;\n    }\n    if (pointers.size > 2) return;\n    gesture = { mode: 'tap', sx: e.clientX, sy: e.clientY, lx: e.clientX, ly: e.clientY, button: e.button, id: e.pointerId, bulldozed: false };\n    if (e.pointerType !== 'mouse') {\n      longTimer = setTimeout(() => {\n        if (gesture && gesture.mode === 'tap') {\n          const t = tileAt(gesture.sx, gesture.sy);\n          if (t) {\n            place(t[0], t[1], EMPTY);\n            try { if (navigator.vibrate) navigator.vibrate(18); } catch (err) { /* ignore */ }\n          }\n          gesture.bulldozed = true;\n        }\n      }, 520);\n    }\n  });\n  world.addEventListener('pointermove', (e) => {\n    if (e.pointerType === 'mouse') {\n      const t = tileAt(e.clientX, e.clientY);\n      hover.show = !!t;\n      if (t) { hover.i = t[0]; hover.j = t[1]; }\n      kbd.show = false;\n    }\n    if (!pointers.has(e.pointerId)) return;\n    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });\n    if (!gesture) return;\n    if (gesture.mode === 'pinch' && pointers.size >= 2) {\n      const [a, b] = Array.from(pointers.values());\n      const d = Math.hypot(a.x - b.x, a.y - b.y);\n      const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;\n      cam.x += mx - gesture.mx; cam.y += my - gesture.my;\n      zoomAt(mx, my, d / (gesture.d || d));\n      gesture.d = d; gesture.mx = mx; gesture.my = my;\n      return;\n    }\n    if (gesture.mode === 'tap' && Math.hypot(e.clientX - gesture.sx, e.clientY - gesture.sy) > 7) {\n      gesture.mode = 'pan';\n      clearTimeout(longTimer);\n      world.classList.add('panning');\n    }\n    if (gesture.mode === 'pan') {\n      cam.x += e.clientX - gesture.lx;\n      cam.y += e.clientY - gesture.ly;\n      gesture.lx = e.clientX; gesture.ly = e.clientY;\n    }\n  });\n  function endPointer(e) {\n    if (!pointers.has(e.pointerId)) return;\n    pointers.delete(e.pointerId);\n    clearTimeout(longTimer);\n    world.classList.remove('panning');\n    if (!gesture) return;\n    if (gesture.mode === 'tap' && e.type === 'pointerup' && !gesture.bulldozed) {\n      const t = tileAt(e.clientX, e.clientY);\n      if (t) place(t[0], t[1], gesture.button === 2 ? EMPTY : TOOL_TYPE[tool]);\n    }\n    if (pointers.size === 0) gesture = null;\n    else if (gesture.mode === 'pinch') gesture = { mode: 'pan', lx: Array.from(pointers.values())[0].x, ly: Array.from(pointers.values())[0].y };\n  }\n  world.addEventListener('pointerup', endPointer);\n  world.addEventListener('pointercancel', endPointer);\n  world.addEventListener('pointerleave', (e) => { if (e.pointerType === 'mouse') hover.show = false; });\n  world.addEventListener('contextmenu', (e) => e.preventDefault());\n  world.addEventListener('wheel', (e) => {\n    e.preventDefault();\n    const f = Math.exp(-clamp(e.deltaY, -120, 120) * 0.0016);\n    zoomAt(e.clientX, e.clientY, f);\n  }, { passive: false });\n\n  for (const b of toolBtns) b.addEventListener('click', () => { selectTool(b.dataset.tool, true); ensureAudio(); });\n\n  document.getElementById('random').addEventListener('click', () => {\n    ensureAudio();\n    randomTown(true);\n    blip(5);\n    toast('A brand-new town, freshly seeded');\n    announce('Generated a random town.');\n  });\n  pauseBtn.addEventListener('click', () => {\n    paused = !paused;\n    pauseBtn.setAttribute('aria-pressed', paused ? 'true' : 'false');\n    pauseBtn.setAttribute('aria-label', paused ? 'Resume the clock' : 'Pause the clock');\n    announce(paused ? 'Clock paused.' : 'Clock running.');\n  });\n  const SPEEDS = [1, 6, 24];\n  speedBtn.addEventListener('click', () => {\n    clockSpeed = SPEEDS[(SPEEDS.indexOf(clockSpeed) + 1) % SPEEDS.length];\n    speedLbl.textContent = clockSpeed + '×';\n    toast(clockSpeed === 1 ? 'Time drifts gently (1×)' : clockSpeed === 6 ? 'Time hurries along (6×)' : 'Days fly by (24×)');\n    announce('Clock speed ' + clockSpeed + ' times.');\n  });\n  function setSoundUI() {\n    soundBtn.setAttribute('aria-pressed', soundOn ? 'true' : 'false');\n    soundBtn.setAttribute('aria-label', soundOn ? 'Sound effects on' : 'Sound effects off');\n  }\n  soundBtn.addEventListener('click', () => {\n    soundOn = !soundOn;\n    store.set('pocket-metropolis-sound', soundOn ? 'on' : 'off');\n    setSoundUI();\n    if (soundOn) ensureAudio();\n    else if (actx && actx.state === 'running') actx.suspend().catch(() => {});\n  });\n\n  window.addEventListener('keydown', (e) => {\n    if (e.metaKey || e.ctrlKey || e.altKey) return;\n    const tag = document.activeElement && document.activeElement.tagName;\n    const k = e.key;\n    const names = ['house', 'tower', 'tree', 'park', 'road', 'water', 'bulldoze'];\n    if (k >= '1' && k <= '7') { selectTool(names[+k - 1], true); return; }\n    if (k === 'r' || k === 'R') { document.getElementById('random').click(); return; }\n    if (k === '+' || k === '=') { zoomAt(W / 2, H / 2, 1.15); return; }\n    if (k === '-' || k === '_') { zoomAt(W / 2, H / 2, 1 / 1.15); return; }\n    if (document.activeElement !== world || tag === 'BUTTON') return;\n    const moves = { ArrowUp: [0, -1], ArrowDown: [0, 1], ArrowLeft: [-1, 0], ArrowRight: [1, 0] };\n    if (moves[k]) {\n      e.preventDefault();\n      kbd.show = true; hover.show = false;\n      kbd.i = clamp(kbd.i + moves[k][0], 0, N - 1);\n      kbd.j = clamp(kbd.j + moves[k][1], 0, N - 1);\n      announce('Tile ' + (kbd.i + 1) + ', ' + (kbd.j + 1) + ': ' + TYPE_NAME[grid[IDX(kbd.i, kbd.j)]] + '.');\n    } else if (k === 'Enter' || k === ' ') {\n      e.preventDefault();\n      ensureAudio();\n      kbd.show = true;\n      place(kbd.i, kbd.j, TOOL_TYPE[tool]);\n    } else if (k === 'Delete' || k === 'Backspace') {\n      e.preventDefault();\n      ensureAudio();\n      place(kbd.i, kbd.j, EMPTY);\n    }\n  });\n  world.addEventListener('focus', () => { if (!hover.show) kbd.show = true; });\n  world.addEventListener('blur', () => { kbd.show = false; });\n\n  window.addEventListener('resize', resize);\n  reduceMQ.addEventListener && reduceMQ.addEventListener('change', (e) => { reduced = e.matches; });\n  window.addEventListener('pagehide', save);\n\n  /* ================================================================\n     Start\n     ================================================================ */\n  setSoundUI();\n  resize();\n  if (load()) { rebuildLife(); recount(true); }\n  else randomTown(true);\n  updateLight();\n  updateClock();\n  start();\n})();\n</script>\n</body>\n</html>\n";
